import { AppDefinition, IncomingAppRequest } from '../app-definition';

// Credentials of the caller must not end up in execution logs.
const HIDDEN_HEADERS = new Set([
  'authorization',
  'proxy-authorization',
  'cookie',
  'x-api-key',
]);

// Any system that can send an HTTP POST. The secret token in the URL is the
// only credential, so every call to a known token is accepted.
export const webhookApp: AppDefinition = {
  key: 'webhook',
  name: 'Webhook',
  description: 'Start when an HTTP POST arrives at the workflow’s own URL',
  icon: 'webhook',
  events: [{ key: 'request', name: 'Incoming request', hasText: false }],
  connection: null,
  routing: 'token',
  ackStatus: 202,

  verify: () => true,

  parse(request) {
    if (!request.token) return [];
    const idempotencyKey = headerValue(request, 'idempotency-key')?.trim();
    return [
      {
        routingKey: request.token,
        eventType: 'request',
        ...(idempotencyKey ? { eventId: idempotencyKey } : {}),
        item: { json: webhookJson(request, new Date()) },
      },
    ];
  },
};

export function webhookJson(
  request: IncomingAppRequest,
  receivedAt: Date,
): Record<string, unknown> {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(request.headers)) {
    if (value === undefined || HIDDEN_HEADERS.has(name.toLowerCase())) continue;
    headers[name.toLowerCase()] = Array.isArray(value)
      ? value.join(', ')
      : value;
  }
  return {
    body: request.body ?? null,
    query: request.query,
    headers,
    received_at: receivedAt.toISOString(),
  };
}

function headerValue(
  request: IncomingAppRequest,
  name: string,
): string | undefined {
  const value = request.headers[name];
  return Array.isArray(value) ? value[0] : value;
}

