// Credentials of the caller must not end up in execution logs.
const HIDDEN_HEADERS = new Set([
  'authorization',
  'proxy-authorization',
  'cookie',
  'x-api-key',
]);

// Any system that can send an HTTP POST. The secret token in the URL is the
// only credential, so every call to a known token is accepted.
export const webhookApp: AppDefinition = {
  key: 'webhook',
  name: 'Webhook',
  description: 'Start when an HTTP POST arrives at the workflow’s own URL',
  icon: 'webhook',
  events: [{ key: 'request', name: 'Incoming request', hasText: false }],
  connection: null,
  routing: 'token',
  ackStatus: 202,

  verify: () => true,

  parse(request) {
    if (!request.token) return [];
    const idempotencyKey = headerValue(request, 'idempotency-key')?.trim();
    return [
      {
        routingKey: request.token,
        eventType: 'request',
        ...(idempotencyKey ? { eventId: idempotencyKey } : {}),
        item: { json: webhookJson(request, new Date()) },
      },
    ];
  },
};

