  return {
    body: request.body ?? null,
    query: request.query,
    headers,
    received_at: receivedAt.toISOString(),
  };
}

function headerValue(
  request: IncomingAppRequest,
  name: string,
): string | undefined {
  const value = request.headers[name];
  return Array.isArray(value) ? value[0] : value;
}

