// An outside application FlowPilot can be triggered by (and maybe reply to).
// Adding an app means adding one AppDefinition: the webhook ingress, the
// trigger routing, the Reply node and the designer only talk to this contract.

export interface AppEventSpec {
  key: string; // e.g. 'message'
  name: string; // e.g. 'New message'
  // The event carries text, so triggers can match keywords on it.
  hasText: boolean;
}

export interface IncomingAppRequest {
  method: 'GET' | 'POST';
  // Second path segment of /api/webhooks/:app/:token (token-routed apps).
  token?: string;
  query: Record<string, unknown>;
  headers: Record<string, string | string[] | undefined>;
  body: unknown;
  rawBody?: Buffer; // exact bytes, for signature checks
}

// Where a Reply goes: put into the trigger item as `conversation`.
export interface ConversationRef {
  app: string;
  recipient_id: string;
  // Added by the triggers module: the connection of the trigger that ran.
  credential_id?: string;
}

export interface AppEvent {
  // Which listener the event is for: the URL token, or e.g. a Page id.
  routingKey: string;
  eventType: string;
  // Same id within 24h is processed once.
  eventId?: string;
  text?: string;
  item: { json: Record<string, unknown> };
}

export interface AppConnection {
  connectorKey: string;
  // Sign-in the designer offers as a "Connect" button: GET startPath (JWT)
  // returns { url } for a pop-up, which reports back with postMessage
  // { type: 'app-oauth-success', connectorKey, credentialIds }. Null: the
  // connection is typed into a form.
  oauth: { startPath: string; label: string } | null;
}

export interface AppDefinition {
  key: string;
  name: string;
  description: string;
  icon: string;
  events: AppEventSpec[];
  connection: AppConnection | null;
  // 'token': <REDACTED> generates a secret URL per trigger node.
  // 'connection': the routing key comes from the trigger's credential.
  routing: 'token' | 'connection';
  routingKeyFromSecret?(secret: <REDACTED>, unknown>): string | null;
  // HTTP status answered for an accepted call.
  ackStatus: number;
  // Setup check some apps make with a GET (returns the body to answer, or
  // null to refuse). Apps without it do not accept GET.
  handshake?(request: IncomingAppRequest): string | null;
  verify(request: IncomingAppRequest): boolean;
  parse(request: IncomingAppRequest): AppEvent[];
  reply?(
    secret: <REDACTED>, unknown>,
    recipientId: string,
    text: string,
  ): Promise<{ messageId: string }>;
  // Longest reply text the app accepts.
  replyMaxLength?: number;
}

// An app API refused or failed a call; `retryable` for rate limits and outages.
export class AppApiError extends Error {
  constructor(
    message: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}
