import { IQueryHandler, QueryHandler } from '@nestjs/cqrs';
import { CheckPublishTriggersQuery } from '@app/designer/application/queries/check-publish-triggers.query';
import type { PublishValidationIssue } from '@app/designer/application/utils';
import { AppDefinition, AppRegistry } from '@app/apps';
import { WorkflowTriggerRepository } from '../../domain/workflow-trigger.repository';
import {
  AppTriggerNode,
  findAppTriggerNodes,
  sharedCondition,
} from '../../domain/workflow-trigger';
import { routingKeyOfConnection } from '../connection-routing';

const CONNECTION_PROBLEMS = {
  NOT_FOUND: 'The selected connection no longer exists. Pick another one.',
  WRONG_APP: 'The selected connection belongs to another app.',
  NO_ROUTING_KEY: 'The selected connection is incomplete. Connect it again.',
} as const;

// Stops a version that could not receive its events, or whose events could
// not be told apart from another workflow's on the same connection.
@QueryHandler(CheckPublishTriggersQuery)
export class CheckPublishTriggersHandler implements IQueryHandler<CheckPublishTriggersQuery> {
  constructor(
    private readonly apps: AppRegistry,
    private readonly repository: WorkflowTriggerRepository,
  ) {}

  async execute(
    query: CheckPublishTriggersQuery,
  ): Promise<PublishValidationIssue[]> {
    const issues: PublishValidationIssue[] = [];
    for (const node of findAppTriggerNodes(query.definition)) {
      const problem = await this.check(node, query);
      if (problem)
        issues.push({ severity: 'error', nodeId: node.nodeId, ...problem });
    }
    return issues;
  }

  private async check(
    node: AppTriggerNode,
    query: CheckPublishTriggersQuery,
  ): Promise<Omit<PublishValidationIssue, 'severity' | 'nodeId'> | null> {
    // A missing app or event is already reported as a required field.
    if (node.app === undefined || node.app === '') return null;
    const app = this.apps.find(node.app);
    if (!app) {
      return {
        code: 'UNKNOWN_APP',
        message: 'Choose an app for this trigger.',
      };
    }
    if (node.event === undefined || node.event === '') return null;
    const event = app.events.find((e) => e.key === node.event);
    if (!event) {
      return {
        code: 'UNKNOWN_EVENT',
        message: `Choose an event of ${app.name}.`,
      };
    }

    if (
      node.matchMode !== node.rawMatchMode ||
      (!event.hasText && node.matchMode !== 'any')
    ) {
      return {
        code: 'INVALID_TRIGGER_CONFIG',
        field: 'match_mode',
        message: `"${event.name}" can only run for every event.`,
      };
    }
    if (node.matchMode !== 'any' && node.keywords.length === 0) {
      return {
        code: 'MISSING_KEYWORDS',
        field: 'keywords',
        message: 'Add at least one keyword, or run for every message.',
      };
    }

    if (app.routing === 'token') return null; // a fresh URL never clashes
    return this.checkConnection(node, app, event.key, query);
  }

  private async checkConnection(
    node: AppTriggerNode,
    app: AppDefinition,
    eventType: string,
    query: CheckPublishTriggersQuery,
  ): Promise<Omit<PublishValidationIssue, 'severity' | 'nodeId'> | null> {
    if (!node.credentialId) {
      return {
        code: 'MISSING_CONNECTION',
        field: 'credential_id',
        message: `Connect ${app.name} for this trigger.`,
      };
    }
    const routing = await routingKeyOfConnection(
      this.repository,
      app,
      node.credentialId,
      query.ownerId,
    );
    if ('error' in routing) {
      return {
        code: 'INVALID_CREDENTIAL',
        field: 'credential_id',
        message: CONNECTION_PROBLEMS[routing.error],
      };
    }

    const listeners = await this.repository.findActiveFor(
      app.key,
      routing.routingKey,
      eventType,
    );
    for (const listener of listeners) {
      if (listener.workflowId === query.workflowId) continue;
      const shared = sharedCondition(node, listener);
      if (!shared) continue;
      const name =
        (await this.repository.findWorkflowName(listener.workflowId)) ??
        'another workflow';
      return {
        code: 'TRIGGER_CONFLICT',
        message: `The workflow "${name}" already runs for ${shared} on this connection. Use other keywords, or change that workflow.`,
      };
    }
    return null;
  }
}
