import { randomBytes } from 'node:crypto';

export const APP_TRIGGER_KEY = 'trigger.app';

export type MatchMode = 'any' | 'keyword' | 'exact';
const MATCH_MODES: readonly MatchMode[] = ['any', 'keyword', 'exact'];

export interface WorkflowTrigger {
  id: string;
  workflowId: string;
  workflowVersionId: string;
  nodeId: string;
  appKey: string;
  eventType: string;
  routingKey: string;
  credentialId: string | null;
  matchMode: MatchMode;
  keywords: string[]; // normalized
  isActive: boolean;
  createdAt: Date;
}

export type NewWorkflowTrigger = Omit<
  WorkflowTrigger,
  'id' | 'workflowId' | 'workflowVersionId' | 'isActive' | 'createdAt'
>;

// An App Trigger node as configured in a definition.
export interface AppTriggerNode {
  nodeId: string;
  app: unknown;
  event: unknown;
  credentialId?: string;
  matchMode: MatchMode;
  keywords: string[]; // normalized, without blanks or repeats
  rawMatchMode: unknown; // as typed, to report invalid values
}

export function findAppTriggerNodes(definition: unknown): AppTriggerNode[] {
  const nodes = (definition as { nodes?: unknown } | null)?.nodes;
  if (!Array.isArray(nodes)) return [];

  const found: AppTriggerNode[] = [];
  for (const node of nodes as Array<{
    id?: unknown;
    data?: { key?: unknown; config?: Record<string, unknown> };
  }>) {
    if (typeof node?.id !== 'string' || node.data?.key !== APP_TRIGGER_KEY) {
      continue;
    }
    const config = node.data.config ?? {};
    const credentialId = config.credential_id;
    const mode = config.match_mode ?? 'any';
    found.push({
      nodeId: node.id,
      app: config.app,
      event: config.event,
      ...(typeof credentialId === 'string' && credentialId
        ? { credentialId }
        : {}),
      matchMode: MATCH_MODES.includes(mode as MatchMode)
        ? (mode as MatchMode)
        : 'any',
      rawMatchMode: mode,
      keywords: parseKeywords(config.keywords),
    });
  }
  return found;
}

// Case, Vietnamese accents and extra spaces do not matter when matching.
export function normalizeText(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// "giá, Bảng giá , ,giá" → ['gia', 'bang gia']
export function parseKeywords(raw: unknown): string[] {
  const list = Array.isArray(raw)
    ? raw
    : typeof raw === 'string'
      ? raw.split(',')
      : [];
  const keywords = list
    .filter((value): value is string => typeof value === 'string')
    .map(normalizeText)
    .filter(Boolean);
  return [...new Set(keywords)];
}

function matches(trigger: WorkflowTrigger, text: string): boolean {
  if (trigger.matchMode === 'any') return true;
  if (trigger.matchMode === 'exact') return trigger.keywords.includes(text);
  return trigger.keywords.some((keyword) => text.includes(keyword));
}

const PRIORITY: Record<MatchMode, number> = { exact: 0, keyword: 1, any: 2 };

// The one listener that handles an event: an exact keyword beats a contained
// keyword, which beats "every message"; ties go to the oldest listener.
export function pickTrigger(
  candidates: readonly WorkflowTrigger[],
  text: string | undefined,
): WorkflowTrigger | undefined {
  const normalized = normalizeText(text ?? '');
  return candidates
    .filter((trigger) => matches(trigger, normalized))
    .sort(
      (a, b) =>
        PRIORITY[a.matchMode] - PRIORITY[b.matchMode] ||
        a.createdAt.getTime() - b.createdAt.getTime(),
    )[0];
}

// Two listeners on the same app, routing key and event clash when an event
// could not be told apart: both catch everything, or both use one keyword
// the same way.
export function sharedCondition(
  a: Pick<WorkflowTrigger, 'matchMode' | 'keywords'>,
  b: Pick<WorkflowTrigger, 'matchMode' | 'keywords'>,
): string | null {
  if (a.matchMode !== b.matchMode) return null;
  if (a.matchMode === 'any') return 'every message';
  const shared = a.keywords.find((keyword) => b.keywords.includes(keyword));
  return shared ? `the keyword "${shared}"` : null;
}

export function generateWebhookToken(): string {
  return randomBytes(32).toString('base64url');
}
