554	export function findAppTriggerNodes(definition: unknown): AppTriggerNode[] {
555	  const nodes = (definition as { nodes?: unknown } | null)?.nodes;
556	  if (!Array.isArray(nodes)) return [];
557	
558	  const found: AppTriggerNode[] = [];
559	  for (const node of nodes as Array<{
560	    id?: unknown;
561	    data?: { key?: unknown; config?: Record<string, unknown> };
562	  }>) {
563	    if (typeof node?.id !== 'string' || node.data?.key !== APP_TRIGGER_KEY) {
564	      continue;
565	    }
566	    const config = node.data.config ?? {};
567	    const credentialId = config.credential_id;
568	    const mode = config.match_mode ?? 'any';
569	    found.push({
570	      nodeId: node.id,
571	      app: config.app,
572	      event: config.event,
573	      ...(typeof credentialId === 'string' && credentialId
574	        ? { credentialId }
575	        : {}),
576	      matchMode: MATCH_MODES.includes(mode as MatchMode)
577	        ? (mode as MatchMode)
578	        : 'any',
579	      rawMatchMode: mode,
580	      keywords: parseKeywords(config.keywords),
581	    });
582	  }
583	  return found;
