586	// Case, Vietnamese accents and extra spaces do not matter when matching.
587	export function normalizeText(text: string): string {
588	  return text
589	    .normalize('NFD')
590	    .replace(/[̀-ͯ]/g, '')
591	    .replace(/đ/g, 'd')
592	    .replace(/Đ/g, 'D')
593	    .toLowerCase()
594	    .replace(/\s+/g, ' ')
595	    .trim();
596	}
