612	function matches(trigger: WorkflowTrigger, text: string): boolean {
613	  if (trigger.matchMode === 'any') return true;
614	  if (trigger.matchMode === 'exact') return trigger.keywords.includes(text);
615	  return trigger.keywords.some((keyword) => text.includes(keyword));
616	}
