32	// The one ingress for every app: verify, parse, route each event to a single
33	// listener, run it once, queue the run. No app-specific code here.
34	@CommandHandler(ReceiveAppEventsCommand)
35	export class ReceiveAppEventsHandler implements ICommandHandler<ReceiveAppEventsCommand> {
36	  private readonly logger = new Logger(ReceiveAppEventsHandler.name);
37	
38	  constructor(
