45	  async execute(
46	    command: ReceiveAppEventsCommand,
47	  ): Promise<ReceiveAppEventsResult> {
48	    const app = this.apps.find(command.appKey);
49	    if (!app) return { outcome: 'unknown-app' };
50	    if (!app.verify(command.request)) return { outcome: 'rejected' };
51	
52	    const started: string[] = [];
53	    let ignored = 0;
54	    let routed = 0;
55	
56	    for (const event of app.parse(command.request)) {
57	      const trigger = pickTrigger(
58	        await this.repository.findActiveFor(
59	          app.key,
60	          event.routingKey,
61	          event.eventType,
62	        ),
63	        event.text,
64	      );
65	      if (!trigger) {
66	        this.logger.debug(
67	          `No ${app.key} listener for ${event.routingKey} / ${event.eventType}`,
68	        );
69	        ignored += 1;
70	        continue;
71	      }
72	      routed += 1;
73	
74	      if (
75	        event.eventId &&
76	        !(await this.dedup.claim(
77	          `dedup:${app.key}:${event.routingKey}:${event.eventId}`,
78	          DEDUP_TTL_SECONDS,
79	        ))
80	      ) {
81	        ignored += 1;
82	        continue;
83	      }
84	
85	      started.push(
86	        await this.commandBus.execute<EnqueueExecutionCommand, string>(
87	          new EnqueueExecutionCommand(trigger.workflowVersionId, [
88	            withConnection(event.item, trigger.credentialId),
89	          ]),
