624	  text: string | undefined,
625	): WorkflowTrigger | undefined {
626	  const normalized = normalizeText(text ?? '');
627	  return candidates
628	    .filter((trigger) => matches(trigger, normalized))
629	    .sort(
630	      (a, b) =>
631	        PRIORITY[a.matchMode] - PRIORITY[b.matchMode] ||
632	        a.createdAt.getTime() - b.createdAt.getTime(),
633	    )[0];
634	}
