import { IncomingAppRequest } from '@app/apps';

export class ReceiveAppEventsCommand {
  constructor(
    readonly appKey: string,
    readonly request: IncomingAppRequest,
  ) {}
}

export type ReceiveAppEventsResult =
  | { outcome: 'unknown-app' }
  | { outcome: 'rejected' } // signature check failed
  | { outcome: 'not-found' } // token-routed app, no listener for the token
  | {
      outcome: 'accepted';
      status: number;
      started: string[]; // execution ids
      ignored: number; // duplicates, events nobody listens for
    };

import { Logger } from '@nestjs/common';
import { CommandBus, CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { AppRegistry } from '@app/apps';
import { EnqueueExecutionCommand } from '@app/execution/application/commands/enqueue-execution/enqueue-execution.command';
import { WorkflowTriggerRepository } from '../../domain/workflow-trigger.repository';
import { pickTrigger } from '../../domain/workflow-trigger';
import { WebhookDedupPort } from '../ports/webhook-dedup.port';

const DEDUP_TTL_SECONDS = 24 * 60 * 60;

// The one ingress for every app: verify, parse, route each event to a single
// listener, run it once, queue the run. No app-specific code here.
@CommandHandler(ReceiveAppEventsCommand)
export class ReceiveAppEventsHandler implements ICommandHandler<ReceiveAppEventsCommand> {
  private readonly logger = new Logger(ReceiveAppEventsHandler.name);

  constructor(
    private readonly apps: AppRegistry,
    private readonly repository: WorkflowTriggerRepository,
    private readonly dedup: WebhookDedupPort,
    private readonly commandBus: CommandBus,
  ) {}

  async execute(
    command: ReceiveAppEventsCommand,
  ): Promise<ReceiveAppEventsResult> {
    const app = this.apps.find(command.appKey);
    if (!app) return { outcome: 'unknown-app' };
    if (!app.verify(command.request)) return { outcome: 'rejected' };

    const started: string[] = [];
    let ignored = 0;
    let routed = 0;

    for (const event of app.parse(command.request)) {
      const trigger = pickTrigger(
        await this.repository.findActiveFor(
          app.key,
          event.routingKey,
          event.eventType,
        ),
        event.text,
      );
      if (!trigger) {
        this.logger.debug(
          `No ${app.key} listener for ${event.routingKey} / ${event.eventType}`,
        );
        ignored += 1;
        continue;
      }
      routed += 1;

      if (
        event.eventId &&
        !(await this.dedup.claim(
          `dedup:${app.key}:${event.routingKey}:${event.eventId}`,
          DEDUP_TTL_SECONDS,
        ))
      ) {
        ignored += 1;
        continue;
      }

      started.push(
        await this.commandBus.execute<EnqueueExecutionCommand, string>(
          new EnqueueExecutionCommand(trigger.workflowVersionId, [
            withConnection(event.item, trigger.credentialId),
          ]),
        ),
      );
    }

    // A wrong URL token is the caller's mistake, worth a 404.
    if (app.routing === 'token' && routed === 0) {
      return { outcome: 'not-found' };
    }
    return { outcome: 'accepted', status: app.ackStatus, started, ignored };
  }
}

// Reply needs to know which connection answers the conversation.
function withConnection(
  item: { json: Record<string, unknown> },
  credentialId: string | null,
): { json: Record<string, unknown> } {
  const conversation = item.json.conversation;
  if (!credentialId || typeof conversation !== 'object' || !conversation) {
    return item;
  }
  return {
    json: {
      ...item.json,
      conversation: { ...conversation, credential_id: credentialId },
    },
  };
}
