import {
  Body,
  Controller,
  ForbiddenException,
  Get,
  Header,
  Headers,
  HttpException,
  Logger,
  NotFoundException,
  Param,
  Post,
  Query,
  Req,
  Res,
  UnauthorizedException,
} from '@nestjs/common';
import type { RawBodyRequest } from '@nestjs/common';
import { CommandBus } from '@nestjs/cqrs';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import type { Request, Response } from 'express';
import { AppRegistry, IncomingAppRequest } from '@app/apps';
import {
  ReceiveAppEventsCommand,
  ReceiveAppEventsResult,
} from '../../application/commands/receive-app-events.command';

// The single entry point for events of every app. Public: callers prove
// themselves with a URL token or the app's signature, never a FlowPilot JWT.
@ApiTags('webhooks')
@Controller('api/webhooks')
export class WebhooksController {
  private readonly logger = new Logger(WebhooksController.name);

  constructor(
    private readonly apps: AppRegistry,
    private readonly commandBus: CommandBus,
  ) {}

  @Get(':app')
  @Header('Content-Type', 'text/plain')
  @ApiOperation({ summary: 'Setup check of an app (e.g. Meta verification)' })
  handshake(
    @Param('app') appKey: string,
    @Query() query: Record<string, unknown>,
    @Headers() headers: Record<string, string>,
  ): string {
    const app = this.apps.find(appKey);
    if (!app?.handshake) throw new NotFoundException('Unknown webhook');
    const answer = app.handshake({ method: 'GET', query, headers, body: null });
    if (answer === null) throw new ForbiddenException('Verification failed');
    return answer;
  }

  @Post([':app', ':app/:token'])
  @ApiOperation({ summary: 'Receive events of an app' })
  async receive(
    @Param('app') appKey: string,
    @Param('token') token: <REDACTED> | undefined,
    @Body() body: unknown,
    @Query() query: Record<string, unknown>,
    @Req() request: RawBodyRequest<Request>,
    @Res({ passthrough: true }) response: Response,
  ) {
    const incoming: IncomingAppRequest = {
      method: 'POST',
      token,
      query,
      headers: request.headers,
      body,
      rawBody: request.rawBody,
    };

    let result: ReceiveAppEventsResult;
    try {
      result = await this.commandBus.execute<
        ReceiveAppEventsCommand,
        ReceiveAppEventsResult
      >(new ReceiveAppEventsCommand(appKey, incoming));
    } catch (error) {
      if (error instanceof HttpException) throw error;
      // Apps (Meta) disable webhooks that keep failing: answer an authentic
      // call normally and keep the error in the server log.
      this.logger.error(
        `Handling ${appKey} events failed: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
      response.status(this.apps.find(appKey)?.ackStatus ?? 200);
      return { success: false };
    }

    switch (result.outcome) {
      case 'unknown-app':
        throw new NotFoundException('Unknown webhook');
      case 'rejected':
        throw new UnauthorizedException('Invalid signature');
      case 'not-found':
        throw new NotFoundException('Webhook not found');
      default:
        response.status(result.status);
        return {
          success: true,
          data: { started: result.started, ignored: result.ignored },
        };
    }
  }
}
