78	// a non-blank string. A connector declaring nothing takes a single api_key.
79	function secretFields(
80	  configSchema: unknown,
81	  values: Record<string, unknown>,
82	): Record<string, string> {
83	  const schema = (configSchema ?? {}) as {
84	    required?: unknown;
85	    properties?: Record<string, unknown>;
86	  };
87	  const declared = Array.isArray(schema.required)
88	    ? schema.required.filter(
89	        (field): field is string => typeof field === 'string',
90	      )
91	    : [];
92	  const required =
93	    declared.length === 0 && Object.keys(schema.properties ?? {}).length === 0
94	      ? ['api_key']
95	      : declared;
96	  const known = new Set([...Object.keys(schema.properties ?? {}), ...required]);
97	
98	  const secret: <REDACTED>, string> = {};
99	  for (const field of known) {
100	    const value = values[field];
101	    if (typeof value === 'string' && value.trim() !== '') {
102	      secret[field] = value.trim();
103	    }
104	  }
