    ownerId: string,
    connectorId: string,
  ): Promise<ConnectorCredential[]> {
    const rows = await this.prisma.connectorCredential.findMany({
      where: { ownerId, connectorId },
      orderBy: { createdAt: 'desc' },
    });
    return rows.map((row) => ConnectorCredentialMapper.toDomain(row));
