// item comes from, with the connection that trigger listened on.
export interface Conversation {
  app: string;
  recipient_id: string;
  credential_id?: string;
}

// The engine calls the node once per input item. Returning an object yields one
// item, an array yields several, null or [] drops the item.
export interface IPerItemExecutor<
  TConfig = unknown,
> extends NodeExecutorBase<TConfig> {
  readonly runMode: 'per_item';

  // The node answers the conversation that started the run (Reply): the engine
  // finds it from the trigger item and uses its connection as the credential.
  readonly usesConversation?: true;

