import { z } from 'zod';
import { AppApiError, AppRegistry } from '@app/apps';
import {
  Conversation,
  IPerItemExecutor,
} from '../../domain/entities/node-executor';
import {
  NodeKeys,
  ReplyLimits,
} from '../../domain/constants/execution.constants';
import { Item, ItemJson } from '../../domain/models/item';
import { Sleep } from './llm-generate-executor';

const ConfigSchema = z.object({
  text: z.string().trim().min(1, 'Reply text must not be empty'),
});

export type ReplyConfig = z.infer<typeof ConfigSchema>;

const defaultSleep: Sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Answers the conversation that started the run, on whatever app it came
// from, with the connection its trigger listened on.
export class ReplyExecutor implements IPerItemExecutor<ReplyConfig> {
  readonly key = NodeKeys.CHAT_REPLY;
  readonly runMode = 'per_item' as const;
  readonly usesConversation = true as const;

  constructor(
    private readonly apps: AppRegistry,
    private readonly sleep: Sleep = defaultSleep,
  ) {}

  parseConfig(raw: unknown): ReplyConfig {
    return ConfigSchema.parse(raw);
  }

  expectedConnectorKey(
    _rawConfig: Record<string, unknown>,
    conversation?: Conversation,
  ): string | null {
    return this.apps.find(conversation?.app)?.connection?.connectorKey ?? null;
  }

  async executeItem(params: {
    config: ReplyConfig;
    item: Item;
    credential: unknown;
    conversation?: Conversation;
  }): Promise<ItemJson> {
    const { conversation } = params;
    const app = this.apps.find(conversation?.app);
    if (!conversation || !app?.reply) {
      throw new Error(
        `Reply is not supported for ${app?.name ?? 'this trigger'}`,
      );
    }
    if (!params.credential || typeof params.credential !== 'object') {
      throw new Error(
        `The ${app.name} trigger has no connection to reply with`,
      );
    }
    const text = params.config.text;
    if (app.replyMaxLength && text.length > app.replyMaxLength) {
      throw new Error(
        `${app.name} replies are limited to ${app.replyMaxLength} characters`,
      );
    }

    const secret = <REDACTED> as Record<string, unknown>;
    const { messageId } = await this.withRetry(() =>
      app.reply!(secret, conversation.recipient_id, text),
    );
    return {
      app: app.key,
      recipient_id: conversation.recipient_id,
      message_id: messageId,
      status: 'sent',
    };
  }

  // Rate limits and outages are retried with a growing pause; anything else
  // (24-hour window, revoked access) fails at once.
  private async withRetry<T>(attempt: () => Promise<T>): Promise<T> {
    for (let retry = 0; ; retry += 1) {
      try {
        return await attempt();
      } catch (error) {
        const retryable = error instanceof AppApiError && error.retryable;
        if (!retryable || retry >= ReplyLimits.MAX_RETRIES) throw error;
        await this.sleep(1000 * 2 ** retry);
      }
    }
  }
}
