          nodeId: node.id,
          nodeKey: node.data.key,
          status: ExecutionStatus.SUCCESS,
          input: items,
          output,
          startedAt,
          finishedAt: new Date(),
        },
        output,
        status: ExecutionStatus.SUCCESS,
      };
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Node execution failed';
      return {
        log: {
          nodeId: node.id,
          nodeKey: node.data?.key ?? 'unknown',
          status: ExecutionStatus.FAILED,
          input: items,
          output: error instanceof ItemRunError ? error.summary : null,
          errorMessage: sanitizeErrorText(message),
          startedAt,
          finishedAt: new Date(),
        },
        output: [],
        status: ExecutionStatus.FAILED,
      };
    }
  }

  private async runOnce(
    executor: IOnceExecutor,
    rawConfig: Record<string, unknown>,
    params: NodeRunParams,
  ): Promise<Item[]> {
    const secret = <REDACTED> this.resolveCredential(
      executor,
      rawConfig,
      params.credentialOwnerId,
    );
    const currentItem = params.items[0] ?? { json: {} };
    const config = executor.parseConfig(
      resolveConfig(
        rawConfig,
        params.configSchema,
        createExpressionContext({
          runs: params.runs,
          names: params.names,
          currentItem,
          currentIndex: 0,
        }),
      ),
    );

    const output = await executor.execute({
      config,
      items: params.items,
      credential: secret,
    });
    if (
      !Array.isArray(output) ||
      !output.every((item) => isPlainObject(item) && isPlainObject(item.json))
    ) {
      throw new Error('Node returned an invalid list of items');
    }
    return output;
  }

  private async runPerItem(
    executor: IPerItemExecutor,
    rawConfig: Record<string, unknown>,
    params: NodeRunParams,
  ): Promise<Item[]> {
    const { items } = params;
    // Nothing to process: no credential lookup, no config validation.
    if (items.length === 0) return [];

    const cap = executor.maxItems?.(rawConfig);
    if (cap && items.length > cap.limit) {
      throw new Error(
        `Node received ${items.length} items, which exceeds ${cap.reason}`,
      );
    }

    // A node answering conversations gets its credential from each item's
    // conversation instead (looked up once per connection).
    const secret = <REDACTED>
      ? null
      : await this.resolveCredential(
          executor,
          rawConfig,
          params.credentialOwnerId,
        );
    const conversationSecrets = new Map<string, Promise<unknown>>();
    const output: Item[] = [];

    for (let index = 0; index < items.length; index += 1) {
      try {
        let credential = secret;
        let conversation: Conversation | undefined;
        if (executor.usesConversation) {
          conversation = conversationOf(params.runs, index);
          const key = conversation.credential_id ?? '';
          if (!conversationSecrets.has(key)) {
            conversationSecrets.set(
              key,
              this.resolveCredential(
                executor,
                rawConfig,
                params.credentialOwnerId,
                conversation.credential_id,
                conversation,
              ),
            );
          }
          credential = await conversationSecrets.get(key);
        }
        const config = executor.parseConfig(
          resolveConfig(
            rawConfig,
            params.configSchema,
            createExpressionContext({
              runs: params.runs,
              names: params.names,
              currentItem: items[index],
              currentIndex: index,
            }),
          ),
        );
        const result = await executor.executeItem({
          config,
          item: items[index],
          credential,
          ...(conversation ? { conversation } : {}),
        });

        const jsons =
          result === null || result === undefined
            ? []
            : Array.isArray(result)
              ? result
              : [result];
        for (const json of jsons) {
          if (!isPlainObject(json)) {
            throw new Error('Node returned an invalid item');
          }
          output.push({ json, pairedItem: index });
        }
      } catch (error) {
        throw new ItemRunError(
          error instanceof Error ? error.message : 'Node execution failed',
          {
            total_items: items.length,
            processed: index,
            failed_at_index: index,
          },
        );
      }
    }
    return output;
  }

  // Runs once per node (not per item); credential_id is never an expression.
  private async resolveCredential(
    executor: INodeExecutor,
    rawConfig: Record<string, unknown>,
    ownerId: string,
    candidate: unknown = rawConfig.credential_id,
    conversation?: Conversation,
  ): Promise<unknown> {
    if (candidate === undefined) return null;
    if (typeof candidate !== 'string' || !UUID_PATTERN.test(candidate)) {
      throw new BadRequestException('Invalid credential ID format');
    }

    const resolved = await this.repository.resolveCredential(
      candidate,
      ownerId,
    );
    if (!resolved) throw new Error('credential was not found');

    const expected = executor.expectedConnectorKey?.(rawConfig, conversation);
    if (expected && resolved.connectorKey !== expected) {
      throw new Error(
        `Credential does not belong to the "${expected}" connector`,
      );
    }
    return resolved.secret;
  }
}

// The conversation of the trigger item the current item descends from
// (following pairedItem back to the first node). When that link is lost (e.g.
// after Aggregate) a trigger that produced a single item still identifies it.
function conversationOf(runs: readonly NodeRun[], index: number): Conversation {
  let json: Record<string, unknown> | undefined;
  let position = index;
  for (let pos = runs.length - 1; pos >= 0; pos -= 1) {
    const item = runs[pos].output[position];
    if (!item) break;
    if (pos === 0) {
      json = item.json;
      break;
    }
    if (item.pairedItem === undefined) break;
    position = item.pairedItem;
  }
  if (!json && runs[0]?.output.length === 1) json = runs[0].output[0].json;

  const conversation = json?.conversation as Partial<Conversation> | undefined;
  if (
    typeof conversation?.app !== 'string' ||
    typeof conversation.recipient_id !== 'string'
  ) {
    throw new Error(
      'Reply needs an App Trigger that receives messages (e.g. Facebook Messenger) at the start of the workflow',
    );
  }
  return conversation as Conversation;
}

function toRecord(value: unknown): Record<string, unknown> {
  return isPlainObject(value) ? value : {};
}

export function sanitizeErrorText(message: string): string {
  return (
    message
      .replace(/\b(?:sk-ant-|sk-)[A-Za-z0-9_-]{16,}/g, '[REDACTED]')
      .replace(/\bAIza[0-9A-Za-z_-]{20,}/g, '[REDACTED]')
      // Meta Page / user access tokens.
      .replace(/\bEAA[A-Za-z0-9]{20,}/g, '[REDACTED]')
      .replace(
        /(access_token|refresh_token|token|encrypted_secret|ENCRYPTION_KEY|client_secret|Bearer <REDACTED>
        '[REDACTED]',
      )
      .replace(/\b[a-fA-F0-9]{32,}\b/g, '[REDACTED]')
  );
}
