import {
  Controller,
  Get,
  HttpException,
  Logger,
  Query,
  Res,
  UseGuards,
} from '@nestjs/common';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import type { Response } from 'express';
import { JwtAuthGuard } from '@app/auth/infrastructure/guards/jwt-auth.guard';
import {
  AuthenticatedUser,
  CurrentUser,
} from '@app/auth/infrastructure/decorators/current-user.decorator';
import { MetaOauthService } from './application/meta-oauth.service';

@ApiTags('integrations')
@Controller('api/integrations/meta')
export class MetaOauthController {
  private readonly logger = new Logger(MetaOauthController.name);

  constructor(private readonly oauth: MetaOauthService) {}

  @Get('auth')
  @ApiBearerAuth()
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Facebook sign-in URL to connect Pages' })
  async auth(@CurrentUser() user: AuthenticatedUser) {
    return { url: await this.oauth.authUrl(user.id) };
  }

  // Facebook redirects the pop-up here; the page reports back to the designer
  // window and closes.
  @Get('callback')
  async callback(
    @Res() res: Response,
    @Query('code') code?: string,
    @Query('state') state?: string,
    @Query('error_description') denied?: string,
  ) {
    try {
      if (!code || !state) {
        throw new Error(denied || 'Facebook sign-in was cancelled');
      }
      const pages = await this.oauth.connect(code, state);
      res.send(
        popupPage({
          type: 'app-oauth-success',
          connectorKey: 'messenger',
          credentialIds: pages.map((page) => page.credentialId),
        }),
      );
    } catch (error) {
      const message =
        error instanceof HttpException || error instanceof Error
          ? error.message
          : 'Connecting the Facebook Page failed';
      this.logger.warn(`Facebook sign-in failed: ${message}`);
      res.status(400).send(
        popupPage({
          type: 'app-oauth-error',
          connectorKey: 'messenger',
          message,
        }),
      );
    }
  }
}

function popupPage(message: Record<string, unknown>): string {
  // "<" escaped so the payload cannot close the script tag.
  const payload = JSON.stringify(message).replace(/</g, '\\u003c');
  return `<!doctype html><meta charset="utf-8"><script>
  if (window.opener) window.opener.postMessage(${payload}, '*');
  window.close();
</script><p>You can close this window.</p>`;
}
import { randomBytes } from 'node:crypto';
import { BadRequestException, Inject, Injectable } from '@nestjs/common';
import { META_GRAPH_API } from '@app/apps';
import type { MetaGraphApi } from '@app/apps/messenger/meta-graph.api';
import { graphVersion } from '@app/apps/messenger/meta-graph.api';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';
import { ConnectorRepository } from '@app/connector/domain/repositories/connector.repository';
import { ConnectorCredentialRepository } from '@app/connector/domain/repositories/connector-credential.repository';
import { ConnectorCredential } from '@app/connector/domain/entities/connector-credential.entity';
import { OauthStateStore } from './ports/oauth-state.store';

const STATE_TTL_SECONDS = 600;
// Read the user's Pages, send messages as them, subscribe them to the app.
const SCOPES = ['pages_show_list', 'pages_messaging', 'pages_manage_metadata'];

export interface ConnectedPage {
  credentialId: string;
  pageId: string;
  name: string;
}

// "Connect Facebook Page": the user signs in to Facebook and picks Pages;
// FlowPilot stores one Messenger connection per Page and makes Meta send the
// Page's messages to the app's webhook. App id / secret are server settings.
@Injectable()
export class MetaOauthService {
  constructor(
    @Inject(META_GRAPH_API) private readonly graph: MetaGraphApi,
    private readonly states: OauthStateStore,
    private readonly connectors: ConnectorRepository,
    private readonly credentials: ConnectorCredentialRepository,
  ) {}

  async authUrl(userId: string): Promise<string> {
    const { appId, redirectUri } = settings();
    const state = randomBytes(24).toString('base64url');
    await this.states.save(state, userId, STATE_TTL_SECONDS);
    const query = new URLSearchParams({
      client_id: appId,
      redirect_uri: redirectUri,
      state,
      response_type: 'code',
      scope: SCOPES.join(','),
    });
    return `https://www.facebook.com/${graphVersion()}/dialog/oauth?${query.toString()}`;
  }

  async connect(code: string, state: string): Promise<ConnectedPage[]> {
    const userId = await this.states.take(state);
    if (!userId) {
      throw new BadRequestException(
        'This sign-in link has expired. Close the window and try again.',
      );
    }
    const { redirectUri } = settings();
    const shortToken = <REDACTED> this.graph.exchangeCode(code, redirectUri);
    const userToken = <REDACTED> this.graph.exchangeLongLived(shortToken);
    const pages = await this.graph.listPages(userToken);
    if (pages.length === 0) {
      throw new BadRequestException(
        'No Facebook Page was shared. Sign in again and select at least one Page.',
      );
    }

    const connector = await this.connectors.findByKey('messenger');
    if (!connector) {
      throw new BadRequestException('The Messenger connector is not set up');
    }
    const encryptionKey = <REDACTED>'ENCRYPTION_KEY'];
    if (!encryptionKey) throw new Error('ENCRYPTION_KEY is not defined');

    const existing = await this.credentials.findByOwnerAndConnector(
      userId,
      connector.id,
    );
    const connected: ConnectedPage[] = [];
    for (const page of pages) {
      await this.graph.subscribePage(page.id, page.accessToken);
      const encryptedSecret = <REDACTED>
        JSON.stringify({
          page_id: page.id,
          page_access_token: <REDACTED>,
          page_name: page.name,
        }),
        encryptionKey,
      );
      // Connecting a Page again refreshes its token instead of adding a copy.
      const previous = existing.find(
        (credential) => pageIdOf(credential, encryptionKey) === page.id,
      );
      let credentialId: string;
      if (previous?.id) {
        await this.credentials.save(
          new ConnectorCredential(
            previous.id,
            connector.id,
            userId,
            page.name,
            encryptedSecret,
            previous.lastTestedAt,
            previous.lastTestStatus,
            previous.createdAt,
          ),
        );
        credentialId = previous.id;
      } else {
        const saved = await this.credentials.create(
          new ConnectorCredential(
            undefined,
            connector.id,
            userId,
            page.name,
            encryptedSecret,
          ),
        );
        credentialId = saved.id!;
      }
      connected.push({ credentialId, pageId: page.id, name: page.name });
    }
    return connected;
  }
}

function settings() {
  const appId = process.env['META_APP_ID'];
  const redirectUri = process.env['META_REDIRECT_URI'];
  if (!appId || !redirectUri || !process.env['META_APP_SECRET']) {
    throw new BadRequestException(
      'Facebook sign-in is not configured on this server (META_APP_ID, META_APP_SECRET, META_REDIRECT_URI)',
    );
  }
  return { appId, redirectUri };
}

function pageIdOf(
  credential: ConnectorCredential,
  encryptionKey: <REDACTED>,
): string | null {
  try {
    const secret = <REDACTED>
      EncryptionUtil.decrypt(credential.encryptedSecret, encryptionKey),
    ) as { page_id?: unknown };
    return typeof secret.page_id === 'string' ? secret.page_id : null;
  } catch {
    return null;
  }
}
// One-time OAuth `state`: proves the callback answers a sign-in this server
// started, and for which user.
export abstract class OauthStateStore {
  abstract save(
    state: string,
    userId: string,
    ttlSeconds: number,
  ): Promise<void>;
  // The user of the state, removed at once so it cannot be replayed.
  abstract take(state: string): Promise<string | null>;
}
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import Redis from 'ioredis';
import { OauthStateStore } from '../../application/ports/oauth-state.store';

@Injectable()
export class RedisOauthStateStore implements OauthStateStore, OnModuleDestroy {
  private readonly redis = new Redis({
    host: process.env['REDIS_HOST'] || 'localhost',
    port: parseInt(process.env['REDIS_PORT'] || '6379', 10),
    password: <REDACTED>'REDIS_PASSWORD'] || undefined,
    lazyConnect: true,
    maxRetriesPerRequest: 3,
  });

  async save(state: string, userId: string, ttlSeconds: number) {
    await this.redis.set(`oauth:state:${state}`, userId, 'EX', ttlSeconds);
  }

  async take(state: string) {
    return this.redis.getdel(`oauth:state:${state}`);
  }

  async onModuleDestroy(): Promise<void> {
    await this.redis.quit().catch(() => undefined);
  }
}
import { ExecutionRepository } from '../../domain/repositories/execution.repository';
import { WorkflowVersionForExecution } from '../../domain/models/execution.types';
import {
  ExecutionStatus,
  TriggerType,
} from '../../domain/constants/execution.constants';
import {
  getExecutionOrder,
  WorkflowDefinition,
} from '../../domain/entities/workflow-execution.entity';
import { INodeExecutor } from '../../domain/entities/node-executor';
import { buildNodeNameIndex, NodeRun } from '../../domain/entities/run-state';
import { Item } from '../../domain/models/item';
import { NodeCatalogPort } from '../ports/node-catalog.port';
import { NodeRunner } from './node-runner';

export interface StartRunInput {
  version: WorkflowVersionForExecution;
  triggerType: TriggerType;
  triggeredById: string | null;
  // Input of the first node: [] for a manual run, the payload for a webhook.
  triggerItems: Item[];
}

// Runs a published version node by node. Shared by the manual (synchronous)
// path and the queue processor (webhook).
export class WorkflowEngine {
  private readonly runner: NodeRunner;

  constructor(
    private readonly repository: ExecutionRepository,
    executors: INodeExecutor[],
    private readonly catalog: NodeCatalogPort,
  ) {
    this.runner = new NodeRunner(
      repository,
      new Map(executors.map((executor) => [executor.key, executor])),
    );
  }

  // Throws when the definition cannot be run, before anything is stored.
  executionOrder(definition: unknown): string[] {
    return getExecutionOrder(definition);
  }

  async createExecution(input: StartRunInput, startedAt: Date) {
    return this.repository.createExecution({
      workflowId: input.version.workflowId,
      workflowVersionId: input.version.id,
      triggerType: input.triggerType,
      triggeredById: input.triggeredById,
      startedAt,
      context:
        input.triggerType === TriggerType.MANUAL
          ? undefined
          : { triggerItems: input.triggerItems },
    });
  }

  async run(
    executionId: string,
    version: WorkflowVersionForExecution,
    triggerItems: Item[],
    startedAt: Date,
  ): Promise<ExecutionStatus> {
    // Stays FAILED if anything unexpected throws (e.g. the database), so the
    // execution is never left RUNNING.
    let finalStatus = ExecutionStatus.FAILED;
    try {
      finalStatus = await this.runNodes(executionId, version, triggerItems);
    } finally {
      const finishedAt = new Date();
      await this.repository.finishExecution(
        executionId,
        finalStatus,
        finishedAt,
        finishedAt.getTime() - startedAt.getTime(),
      );
    }
    return finalStatus;
  }

  private async runNodes(
    executionId: string,
    version: WorkflowVersionForExecution,
    triggerItems: Item[],
  ): Promise<ExecutionStatus> {
    const order = this.executionOrder(version.definition);
    const definition = version.definition as WorkflowDefinition;
    const nodes = new Map(definition.nodes.map((node) => [node.id, node]));
    const names = buildNodeNameIndex(definition.nodes);
    // A malformed node without a key must fail on its own (no executor),
    // not break the catalog lookup for the whole run.
    const nodeKeys = definition.nodes
      .map((node) => node.data?.key)
      .filter((key): key is string => typeof key === 'string');
    const configSchemas = await this.catalog.getConfigSchemas([
      ...new Set(nodeKeys),
    ]);

    const runs: NodeRun[] = [];
    let items: Item[] = triggerItems;
    let status = ExecutionStatus.SUCCESS;

    for (const nodeId of order) {
      const node = nodes.get(nodeId)!;
      const result = await this.runner.run({
        node,
        items,
        runs,
        names,
        configSchema: configSchemas.get(node.data?.key),
        credentialOwnerId: version.workflowOwnerId,
      });

      await this.repository.saveNodeLog(executionId, result.log);

      if (result.status === ExecutionStatus.FAILED) {
        status = ExecutionStatus.FAILED;
        break;
      }
      runs.push({
        nodeId: node.id,
        nodeName: typeof node.data.name === 'string' ? node.data.name : node.id,
        input: items,
        output: result.output,
      });
      items = result.output;
    }
    return status;
  }
}

