// config_schema of the MVP node types. Plain data (no imports) so the seed and
// the execution tests share a single source of truth.

export const MANUAL_TRIGGER_CONFIG_SCHEMA = {
  type: 'object',
  properties: {},
};

// One trigger node for every outside app (libs/apps). The designer draws its
// form from GET /api/trigger-apps (x-display); the backend checks the app,
// event, connection and keywords on publish.
export const APP_TRIGGER_CONFIG_SCHEMA = {
  type: 'object',
  required: ['app', 'event'],
  'x-display': 'appTrigger',
  properties: {
    app: { type: 'string', title: 'App' },
    event: { type: 'string', title: 'Event' },
    credential_id: {
      type: 'string',
      title: 'Connection',
      'x-refType': 'credential',
    },
    match_mode: {
      type: 'string',
      title: 'Run when',
      enum: ['any', 'keyword', 'exact'],
      default: 'any',
    },
    keywords: { type: 'string', title: 'Keywords' },
  },
};

// Answers the conversation that started the run (the trigger's app and
// connection), so the user only writes the text.
export const CHAT_REPLY_CONFIG_SCHEMA = {
  type: 'object',
  required: ['text'],
  properties: {
    text: {
      type: 'string',
      title: 'Text',
      description:
        'Sent back to the person who wrote, on the app and Page that started this workflow.',
      'x-allowExpression': true,
      'x-multiline': true,
    },
  },
};

export const GOOGLE_SHEET_READ_ROWS_CONFIG_SCHEMA = {
  type: 'object',
  required: ['credential_id', 'spreadsheet_id', 'sheet_name'],
  'x-propertyOrder': ['credential_id', 'spreadsheet_id', 'sheet_name'],
  properties: {
    credential_id: { type: 'string', 'x-connectorKey': 'google' },
    spreadsheet_id: { type: 'string' },
    sheet_name: { type: 'string' },
  },
};

// `field` is a path inside the item (e.g. "status", "data.label"), not an expression.
export const FILTER_CONFIG_SCHEMA = {
  type: 'object',
  required: ['field', 'operator', 'value'],
  'x-propertyOrder': ['field', 'operator', 'value'],
  properties: {
    field: { type: 'string' },
    operator: { type: 'string', enum: ['equals', 'not_equals', 'contains'] },
    value: { type: 'string', 'x-allowExpression': true },
  },
};

// `to` defaults to the item's email so workflows published before the field existed keep working.
export const GMAIL_SEND_CONFIG_SCHEMA = {
  type: 'object',
  required: ['credential_id', 'to', 'subject', 'body'],
  'x-propertyOrder': ['credential_id', 'to', 'subject', 'body'],
  properties: {
    credential_id: { type: 'string', 'x-connectorKey': 'google' },
    to: {
      type: 'string',
      'x-allowExpression': true,
      default: '{{$json.email}}',
    },
    subject: { type: 'string', 'x-allowExpression': true },
    body: { type: 'string', 'x-allowExpression': true },
  },
};

export const AGGREGATE_CONFIG_SCHEMA = {
  type: 'object',
  properties: {
    field: { type: 'string', default: 'items' },
  },
};

// One node for every LLM vendor: `provider` picks the vendor, and the credential
// must belong to it (x-connectorKeyFrom). prompt / system_prompt take expressions.
export const LLM_GENERATE_CONFIG_SCHEMA = {
  type: 'object',
  required: ['provider', 'credential_id', 'model', 'prompt'],
  'x-propertyOrder': [
    'provider',
    'credential_id',
    'model',
    'system_prompt',
    'prompt',
    'output_format',
    'max_tokens',
    'temperature',
    'max_items',
  ],
  properties: {
    provider: {
      type: 'string',
      title: 'Provider',
      enum: ['anthropic', 'openai', 'gemini'],
    },
    credential_id: {
      type: 'string',
      title: 'Credential',
      'x-refType': 'credential',
      'x-connectorKeyFrom': 'provider',
    },
    model: {
      type: 'string',
      title: 'Model',
      // Grey hint in the box; models change often, so it is free text, not a list.
      'x-placeholderByField': {
        field: 'provider',
        values: {
          anthropic: 'e.g. claude-opus-5-5',
          openai: 'e.g. gpt-4o-mini',
          gemini: 'e.g. gemini-2.0-flash',
        },
      },
    },
    system_prompt: {
      type: 'string',
      title: 'System prompt',
      'x-allowExpression': true,
      'x-multiline': true,
    },
    prompt: {
      type: 'string',
      title: 'Prompt',
      'x-allowExpression': true,
      'x-multiline': true,
    },
    output_format: {
      type: 'string',
      title: 'Output format',
      enum: ['text', 'json'],
      default: 'text',
    },
    max_tokens: {
      type: 'integer',
      title: 'Max tokens',
      minimum: 1,
      default: 1024,
    },
    temperature: { type: 'number', title: 'Temperature', minimum: 0 },
    max_items: {
      type: 'integer',
      title: 'Max items',
      minimum: 1,
      default: 50,
    },
  },
};

// API-key connectors share one shape: a single secret field.
export const API_KEY_CONNECTOR_CONFIG_SCHEMA = {
  type: 'object',
  required: ['api_key'],
  properties: {
    api_key: <REDACTED>
      type: 'string',
      title: 'API Key',
      'x-secret': <REDACTED>,
      'x-testable': true,
    },
  },
};

// Facebook Page connection: filled by "Connect Facebook Page" (OAuth), or
// typed in from the Meta app dashboard. page_id routes incoming messages.
export const MESSENGER_CONNECTOR_CONFIG_SCHEMA = {
  type: 'object',
  required: ['page_id', 'page_access_token'],
  'x-propertyOrder': ['page_id', 'page_access_token'],
  properties: {
    page_id: { type: 'string', title: 'Page ID' },
    page_access_token: <REDACTED>
      type: 'string',
      title: 'Page Access Token',
      'x-secret': <REDACTED>,
    },
  },
};
## Nguyên tắc chung

Mục tiêu "dễ mở rộng" = **thêm connector/node type mới chỉ cần INSERT row + viết 1 executor**, không sửa: engine, Designer UI, validation logic. Muốn vậy, schema phải tự mô tả đủ 3 thứ: *cách hiển thị*, *cách validate*, *cách engine xử lý runtime* — không được để bất kỳ thông tin nào trong 3 thứ đó nằm hard-code trong code.

---

## A. `connectors.config_schema` — chuẩn field

Ngoài JSON Schema gốc, cố định 1 bộ `x-*` key dùng xuyên suốt:

```json
{
  "type": "object",
  "properties": {
    "apiKey": <REDACTED>
      "type": "string",
      "title": "API Key",
      "x-secret": <REDACTED>,
      "x-testable": true
    },
    "workspace": {
      "type": "string",
      "title": "Workspace URL"
    }
  },
  "required": ["apiKey"]
}
```

| Field | Bắt buộc? | Vai trò |
|---|---|---|
| `type`, `properties`, `required` | Có | JSON Schema chuẩn — validate form kết nối |
| `title` | Có | Label hiển thị, tránh hard-code chuỗi tiếng Việt trong FE |
| `x-secret: <REDACTED>` | Nên có với mọi field OAuth token/API key | Báo cho: (1) UI render input dạng password, (2) tầng lưu trữ biết field này phải đi vào `encrypted_secret` chứ không lưu plaintext ở đâu khác |
| `x-testable: true` | Tuỳ chọn | Đánh dấu field then chốt để hàm "Test Connection" (FR-CF-04, cập nhật `last_test_status`) biết cần field nào để gọi thử API |

**Điểm mấu chốt:** `auth_type` (`OAUTH2`/`API_KEY`/`BASIC`/`NONE`) quyết định **luồng lấy secret** (redirect OAuth vs form nhập tay), còn `config_schema` chỉ mô tả **field phụ đi kèm** sau khi đã có secret (VD workspace slug). Đừng nhét cả access_token/refresh_token vào `config_schema` — 2 thứ đó luôn đi thẳng vào `connector_credentials.encrypted_secret`, không qua schema validate vì chúng do provider trả về, không do user gõ.

---

## B. `node_type_definitions` — 3 schema, áp dụng nhất quán bộ `x-*` sau

```json
{
  "config_schema": {
    "type": "object",
    "properties": {
      "credential_id": {
        "type": "string",
        "title": "Tài khoản",
        "x-refType": "credential",
        "x-connectorKey": "gmail"
      },
      "to": {
        "type": "string",
        "title": "Người nhận",
        "x-allowExpression": true
      },
      "subject": {
        "type": "string",
        "title": "Tiêu đề",
        "x-allowExpression": true
      }
    },
    "required": ["credential_id", "to", "subject"]
  },
  "input_schema": null,
  "output_schema": {
    "type": "object",
    "properties": {
      "message_id": { "type": "string" },
      "delivered": { "type": "boolean" }
    }
  }
}
```

| `x-*` field | Đặt ở đâu | Engine/UI dùng để làm gì |
|---|---|---|
| `x-refType: "credential"` | `config_schema` | UI render credential picker; **engine dùng để biết field nào cần gửi qua `CredentialVault.decrypt()`** trước khi truyền vào executor — tránh executor tự phải biết field nào là credential_id |
| `x-connectorKey` | `config_schema`, field kiểu `x-refType: credential` | Filter danh sách credential đúng connector (không cho chọn nhầm credential Slack cho node Gmail) — validate được cả ở DB lẫn UI |
