import { useCallback } from 'react';
import { Input } from '@/components/ui/input';
import { useTriggerApps } from '../../hooks/useWorkflowTriggers';
import { useAppOAuth } from '../../hooks/useAppOAuth';
import { MATCH_MODE_LABELS, triggerService } from '../../services/trigger.service';
import type { MatchMode } from '../../types/trigger.types';
import { CredentialPicker } from './CredentialField';
import { EnumField } from './EnumField';
import { FieldShell } from './FieldShell';
import { WebhookUrlField } from './WebhookUrlField';

interface AppTriggerFieldsProps {
  workflowId: string;
  nodeId: string;
  config: Record<string, unknown>;
  onChange: (key: string, value: unknown) => void;
  onReplaceConfig: (config: Record<string, unknown>) => void;
}

const MATCH_MODES = Object.keys(MATCH_MODE_LABELS) as MatchMode[];

// App → Event → Connection → Run when. Everything comes from the app catalog,
// so a new app shows up here without frontend changes.
export function AppTriggerFields({
  workflowId,
  nodeId,
  config,
  onChange,
  onReplaceConfig,
}: AppTriggerFieldsProps) {
  const { data: apps = [], isLoading, isError } = useTriggerApps();
  const app = apps.find((candidate) => candidate.key === config.app);
  const event = app?.events.find((candidate) => candidate.key === config.event);
  const matchMode = MATCH_MODES.includes(config.match_mode as MatchMode)
    ? (config.match_mode as MatchMode)
    : 'any';

  const selectCredential = useCallback(
    (credentialId: string) => onChange('credential_id', credentialId),
    [onChange],
  );
  const oauth = useAppOAuth(
    app?.connection?.connectorKey,
    app?.connection?.oauth?.startPath,
    selectCredential,
  );

  if (isError) {
    return <p className="text-sm text-destructive">The list of apps could not be loaded.</p>;
  }

  return (
    <>
      <EnumField
        id="field-app"
        label="App"
        options={apps.map((candidate) => candidate.key)}
        labels={Object.fromEntries(apps.map((candidate) => [candidate.key, candidate.name]))}
        value={typeof config.app === 'string' ? config.app : ''}
        onChange={(key) =>
          onReplaceConfig(
            triggerService.configForApp(
              config,
              apps.find((candidate) => candidate.key === key),
            ),
          )
        }
      />
      {isLoading && <p className="text-xs text-muted-foreground">Loading apps...</p>}
      {app && <p className="-mt-2 text-[11px] text-muted-foreground">{app.description}</p>}

      {app && app.events.length > 1 && (
        <EnumField
          id="field-event"
          label="Event"
          options={app.events.map((candidate) => candidate.key)}
          labels={Object.fromEntries(
            app.events.map((candidate) => [candidate.key, candidate.name]),
          )}
          value={typeof config.event === 'string' ? config.event : ''}
          onChange={(key) => onChange('event', key)}
        />
      )}

      {app?.connection && (
        <CredentialPicker
          id="field-credential_id"
          label="Connection"
          connectorKey={app.connection.connectorKey}
          value={typeof config.credential_id === 'string' ? config.credential_id : ''}
          onChange={selectCredential}
          signIn={
            app.connection.oauth
              ? {
                  label: app.connection.oauth.label,
                  onClick: () => void oauth.connect(),
                  pending: oauth.pending,
                  error: oauth.error,
                }
              : undefined
          }
        />
      )}

      {app?.routing === 'token' && <WebhookUrlField workflowId={workflowId} nodeId={nodeId} />}

      {event?.hasText && (
        <>
          <EnumField
            id="field-match_mode"
            label="Run when"
            options={MATCH_MODES}
            labels={MATCH_MODE_LABELS}
            value={matchMode}
            onChange={(mode) => onChange('match_mode', mode)}
          />
          {matchMode !== 'any' && (
            <FieldShell
              id="field-keywords"
              label="Keywords"
              hint="Separate with commas. Case and accents do not matter. A message runs only one workflow: exact keywords first, then keywords, then “Every message”."
            >
              <Input
                id="field-keywords"
                value={typeof config.keywords === 'string' ? config.keywords : ''}
                placeholder="e.g. giá, bảng giá"
                onChange={(e) => onChange('keywords', e.target.value)}
              />
            </FieldShell>
          )}
        </>
      )}
    </>
  );
}
import { useCallback, useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { triggerService } from '../services/trigger.service';
import { credentialKeys } from './useCredentials';

interface OAuthMessage {
  type?: unknown;
  connectorKey?: unknown;
  credentialIds?: unknown;
  message?: unknown;
}

// "Connect <app>" sign-in in a pop-up. The pop-up posts back
// { type: 'app-oauth-success' | 'app-oauth-error', connectorKey, ... }; the new
// connections are listed again and the first one is handed to onConnected.
export function useAppOAuth(
  connectorKey: string | undefined,
  startPath: string | undefined,
  onConnected: (credentialId: string) => void,
) {
  const queryClient = useQueryClient();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!connectorKey) return;
    const handle = (event: MessageEvent<OAuthMessage>) => {
      if (event.data?.connectorKey !== connectorKey) return;
      if (event.data.type === 'app-oauth-success') {
        setPending(false);
        setError(null);
        void queryClient.invalidateQueries({ queryKey: credentialKeys.list(connectorKey) });
        const ids = event.data.credentialIds;
        if (Array.isArray(ids) && typeof ids[0] === 'string') onConnected(ids[0]);
      } else if (event.data.type === 'app-oauth-error') {
        setPending(false);
        setError(typeof event.data.message === 'string' ? event.data.message : 'Sign-in failed');
      }
    };
    window.addEventListener('message', handle);
    return () => window.removeEventListener('message', handle);
  }, [connectorKey, onConnected, queryClient]);

  const connect = useCallback(async () => {
    if (!startPath) return;
    setError(null);
    setPending(true);
    try {
      const url = await triggerService.oauthUrl(startPath);
      const popup = window.open(url, 'app-oauth', 'width=600,height=700');
      // Closing the pop-up without finishing must not leave the button waiting.
      const watch = window.setInterval(() => {
        if (!popup || popup.closed) {
          window.clearInterval(watch);
          setPending(false);
        }
      }, 500);
    } catch (cause) {
      setPending(false);
      setError(cause instanceof Error ? cause.message : 'Sign-in could not start');
    }
  }, [startPath]);

  return { connect, pending, error };
}
import { useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useWorkflowTriggers } from '../../hooks/useWorkflowTriggers';
import { triggerService } from '../../services/trigger.service';
import { FieldShell } from './FieldShell';

interface WebhookUrlFieldProps {
  workflowId: string;
  nodeId: string;
}

// Read-only: the URL is created when the workflow is published.
export function WebhookUrlField({ workflowId, nodeId }: WebhookUrlFieldProps) {
  const { data: triggers, isLoading } = useWorkflowTriggers(workflowId, nodeId);
  const [copied, setCopied] = useState(false);
  const url = triggerService.findForNode(triggers, nodeId)?.webhookUrl ?? null;

  const copy = () => {
    if (!url) return;
    navigator.clipboard
      .writeText(url)
      .then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      })
      .catch(() => undefined);
  };

  const hint = url
    ? 'POST JSON to this URL to run the published version. It stays the same when you publish again.'
    : isLoading
      ? 'Loading…'
      : 'Publish the workflow to get its URL.';

  return (
    <FieldShell id="webhook-url" label="Webhook URL" hint={hint}>
      <div className="flex gap-2">
        <Input
          id="webhook-url"
          readOnly
          value={url ?? ''}
          placeholder="Not published yet"
          className="font-mono text-xs"
          onFocus={(e) => e.target.select()}
        />
        <Button
          type="button"
          variant="outline"
          size="icon"
          onClick={copy}
          disabled={!url}
          aria-label="Copy webhook URL"
        >
          {copied ? <Check className="size-4" /> : <Copy className="size-4" />}
        </Button>
      </div>
    </FieldShell>
  );
}
