// Shown instead of the Run button: an App Trigger version runs by itself when
// its app sends an event (apps routed by URL show that URL).
export function AppTriggerInfo({ workflowId, versionId, nodeId, appKey }: AppTriggerInfoProps) {
  const { data: triggers, isLoading } = useWorkflowTriggers(workflowId);
  const { data: apps = [] } = useTriggerApps();
  const [copied, setCopied] = useState(false);
  const appName = apps.find((app) => app.key === appKey)?.name ?? 'the app';
  const trigger = triggerService.findForNode(triggers, nodeId);
  const isCurrent = trigger?.workflowVersionId === versionId;
  const url = isCurrent ? trigger?.webhookUrl : null;

  const copy = () => {
    if (!url) return;
    navigator.clipboard
      .writeText(url)
      .then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      })
      .catch(() => undefined);
  };

  return (
