import { Module } from '@nestjs/common';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { DesignerModule } from '@app/designer';
import { PrismaModule } from '@app/database';
import { AuthModule } from '../../../libs/auth/src';
import { NodeLibraryModule } from '../../../libs/node-library/src';
import { ConnectorModule } from '../../../libs/connector/src';
import { IntegrationsModule } from '@app/integrations';
import { ExecutionModule } from '@app/execution';
import { TriggersModule } from '@app/triggers';

@Module({
  imports: [
    DesignerModule,
    PrismaModule,
    AuthModule,
    NodeLibraryModule,
    ConnectorModule,
    IntegrationsModule,
    ExecutionModule,
    TriggersModule,
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}
import { NestFactory } from '@nestjs/core';
import { NestExpressApplication } from '@nestjs/platform-express';
import { AppModule } from './app.module';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';

import { ValidationPipe } from '@nestjs/common';

try {
  process.loadEnvFile();
} catch {
  // If .env file does not exist, ignore
}

async function bootstrap() {
  // rawBody: webhook signatures (Messenger, Zalo) are computed on the exact bytes.
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });
  app.useBodyParser('json', { limit: '1mb' });
  app.enableCors();
  app.useGlobalPipes(new ValidationPipe({ whitelist: true, transform: true }));

  const config = new DocumentBuilder()
    .setTitle('FlowPilot API')
    .setDescription('The FlowPilot backend API description')
    .setVersion('1.0')
    .build();
  const documentFactory = () => SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, documentFactory);

  await app.listen(process.env.PORT ?? 8080);
}
bootstrap().catch((err) => console.error(err));
