import axios, { AxiosError } from 'axios';
import { AppApiError } from '../core/package';

export const GRAPH_VERSION = 'v23.0';
const REQUEST_TIMEOUT_MS = 15_000;

export interface FacebookPage {
  id: string;
  name: string;
  accessToken: <REDACTED>;
}

export interface AppSubscription {
  object: string;
  callbackUrl: string;
  active: boolean;
}

// The Facebook Graph API calls the Messenger package makes; replaced by a fake
// in tests. The Meta App (id + secret) is the user's own, from the credential.
export interface MetaGraphApi {
  // OAuth: code → short-lived user token → long-lived user token.
  exchangeCode(
    appId: string,
    appSecret: <REDACTED>,
    code: string,
    redirectUri: string,
  ): Promise<string>;
  exchangeLongLived(
    appId: string,
    appSecret: <REDACTED>,
    userToken: <REDACTED>,
  ): Promise<{ token: <REDACTED>; expiresIn: number | null }>;
  // Pages the user granted, each with a Page token (never expires when it
  // comes from a long-lived user token).
  listPages(userToken: <REDACTED> Promise<FacebookPage[]>;
  sendText(
    pageAccessToken: <REDACTED>,
    recipientId: string,
    text: string,
  ): Promise<{ messageId: string }>;
  // App webhook subscription (app token = <REDACTED>
  listAppSubscriptions(appId: string, appToken: <REDACTED> Promise<AppSubscription[]>;
  subscribeApp(
    appId: string,
    appToken: <REDACTED>,
    subscription: { callbackUrl: string; verifyToken: <REDACTED>; fields: string[] },
  ): Promise<void>;
  unsubscribeApp(appId: string, appToken: <REDACTED> Promise<void>;
  // Which apps receive a Page's events.
  pageSubscribedAppIds(pageId: string, pageAccessToken: <REDACTED> Promise<string[]>;
  subscribePage(pageId: string, pageAccessToken: <REDACTED> Promise<void>;
  unsubscribePage(pageId: string, pageAccessToken: <REDACTED> Promise<void>;
}

export class HttpMetaGraphApi implements MetaGraphApi {
  async exchangeCode(
    appId: string,
    appSecret: <REDACTED>,
    code: string,
    redirectUri: string,
  ) {
    const data = await this.call<{ access_token: <REDACTED> }>(
      'get',
      'oauth/access_token',
      {
        client_id: appId,
        client_secret: <REDACTED>,
        redirect_uri: redirectUri,
        code,
      },
    );
    return data.access_token;
  }

  async exchangeLongLived(appId: string, appSecret: <REDACTED>, userToken: <REDACTED> {
    const data = await this.call<{ access_token: <REDACTED>; expires_in?: number }>(
      'get',
      'oauth/access_token',
      {
        client_id: appId,
        client_secret: <REDACTED>,
        grant_type: 'fb_exchange_token',
        fb_exchange_token: <REDACTED>,
      },
    );
    return { token: <REDACTED>, expiresIn: data.expires_in ?? null };
  }

  async listPages(userToken: <REDACTED> {
    const data = await this.call<{
      data?: Array<{ id: string; name: string; access_token: <REDACTED> }>;
