154	  private async runPerItem(
155	    executor: IPerItemExecutor,
156	    rawConfig: Record<string, unknown>,
157	    params: NodeRunParams,
158	  ): Promise<Item[]> {
159	    const { items } = params;
160	    // Nothing to process: no credential lookup, no config validation.
161	    if (items.length === 0) return [];
162	
163	    const cap = executor.maxItems?.(rawConfig);
164	    if (cap && items.length > cap.limit) {
165	      throw new Error(
166	        `Node received ${items.length} items, which exceeds ${cap.reason}`,
167	      );
168	    }
169	
170	    const secret = <REDACTED> this.resolveCredential(
171	      executor,
172	      rawConfig,
173	      params.credentialOwnerId,
174	    );
175	    const output: Item[] = [];
176	
177	    for (let index = 0; index < items.length; index += 1) {
178	      try {
179	        const config = executor.parseConfig(
180	          resolveConfig(
181	            rawConfig,
182	            params.configSchema,
183	            createExpressionContext({
184	              runs: params.runs,
185	              names: params.names,
186	              currentItem: items[index],
187	              currentIndex: index,
188	            }),
189	          ),
190	        );
