192	          config,
193	          item: items[index],
194	          credential: secret,
195	        });
196	
197	        const jsons =
198	          result === null || result === undefined
199	            ? []
200	            : Array.isArray(result)
201	              ? result
202	              : [result];
203	        for (const json of jsons) {
