    listeners: NewListener[],
  ) {
    this.listeners = this.listeners.filter((l) => l.workflowId !== workflowId);
    if (workflowVersionId) {
      for (const listener of listeners) {
        this.listeners.push({
          ...listener,
          id: randomUUID(),
          workflowId,
          workflowVersionId,
        });
