        id: ownerId,
        email: 'webhook-e2e@flowpilot.local',
        passwordHash: 'dummy',
        name: 'Webhook E2E User',
      },
    });
  });

  afterAll(async () => {
    await app.close();
  });

  it('runs the published version in the background when the URL is called', async () => {
    const workflowId = await createWorkflow('Webhook e2e');
    const v1 = await publish(workflowId, 'urgent');
    const path = await webhookPath(workflowId, v1);
    expect(path).toMatch(/^\/api\/webhooks\/webhook\/[A-Za-z0-9_-]{43}$/);

