import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { FieldShell } from './FieldShell';

interface EnumFieldProps {
  id: string;
  label: string;
  options: string[];
  // Shown instead of the raw option value.
  labels?: Record<string, string>;
  value: string;
  onChange: (value: string) => void;
}

export function EnumField({ id, label, options, labels, value, onChange }: EnumFieldProps) {
  const labelOf = (option: string) => labels?.[option] ?? option;
  return (
    <FieldShell id={id} label={label}>
      <Select
        value={value || null}
        onValueChange={(next) => next !== null && onChange(next)}
        items={options.map((option) => ({ value: option, label: labelOf(option) }))}
      >
        <SelectTrigger id={id} className="w-full">
          <SelectValue placeholder={`Select ${label.toLowerCase()}`} />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option} value={option}>
              {labelOf(option)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
  );
}
import type { ReactNode } from 'react';
import { Label } from '@/components/ui/label';

interface FieldShellProps {
  id: string;
  label: string;
  expression?: boolean;
  hint?: ReactNode;
  children: ReactNode;
}

// Label, optional "fx" marker (the field accepts expressions) and hint around a control.
export function FieldShell({ id, label, expression, hint, children }: FieldShellProps) {
  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between">
        <Label htmlFor={id} className="capitalize">
          {label}
        </Label>
        {expression && (
          <span className="rounded border border-purple-200 bg-purple-100 px-1.5 py-0.5 font-mono text-[10px] text-purple-700">
            fx
          </span>
        )}
      </div>
      {children}
      {hint && <p className="text-[11px] text-muted-foreground">{hint}</p>}
    </div>
  );
}
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { FieldShell } from './FieldShell';

interface TextFieldProps {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  multiline?: boolean;
  expression?: boolean;
  placeholder?: string;
  // Field-specific guidance (schema `description`); replaces the generic one.
  hint?: string;
}

export function TextField({
  id,
  label,
  value,
  onChange,
  multiline,
  expression,
  placeholder,
  hint: fieldHint,
}: TextFieldProps) {
  const hint =
    fieldHint ??
    (expression ? 'Use {{$json.column}} or {{$node["Node name"].json.column}}' : undefined);

  return (
    <FieldShell id={id} label={label} expression={expression} hint={hint}>
      {multiline ? (
        <Textarea
          id={id}
          value={value}
          rows={5}
          placeholder={placeholder}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <Input
          id={id}
          value={value}
          placeholder={placeholder ?? (expression ? '{{$json.field}}' : `Enter ${label.toLowerCase()}`)}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
    </FieldShell>
  );
}
export interface NodeType {
  id: string;
  key: string;
  displayName: string;
  icon: string;
  color: string;
  category: 'TRIGGER' | 'LOGIC' | 'DATA_PROCESSING' | 'INTEGRATION' | 'AI';
  description: string;
  configSchema: {
    type: 'object';
    required?: string[];
    properties: Record<string, unknown>;
  };
  inputSchema: unknown;
  outputSchema: unknown;
  connectorId: string | null;
  isActive: boolean;
}
import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios';
import { useAuthStore } from '../../features/auth/store/auth.store';

const BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:8081';

export const apiClient = axios.create({
  baseURL: BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

let isRefreshing = false;
let failedQueue: Array<{
  resolve: (token: <REDACTED> => void;
  reject: (error: unknown) => void;
}> = [];

const processQueue = (error: unknown, token: <REDACTED> | null = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else if (token) {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

