import { useCallback, useEffect, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { errorMessage, triggerService } from '../services/trigger.service';
import type {
  ActivationState,
  NodeOption,
  NodeWebhook,
  TestListen,
} from '../types/trigger.types';

export const triggerKeys = {
  activation: (workflowId: string) => ['workflow-activation', workflowId] as const,
  webhooks: (workflowId: string) => ['workflow-webhooks', workflowId] as const,
  options: (nodeKey: string, property: string, credentialId: string | undefined) =>
    ['node-options', nodeKey, property, credentialId ?? ''] as const,
};

export function useActivation(workflowId: string | undefined) {
  return useQuery<ActivationState>({
    queryKey: triggerKeys.activation(workflowId ?? ''),
    queryFn: () => triggerService.activation(workflowId as string),
    enabled: !!workflowId,
  });
}

export function useSetActive(workflowId: string) {
  const queryClient = useQueryClient();
  return useMutation<ActivationState, Error, boolean>({
    mutationFn: (active) => triggerService.setActive(workflowId, active),
    onSuccess: (state) => {
      queryClient.setQueryData(triggerKeys.activation(workflowId), state);
    },
  });
}

// URLs of the draft's trigger nodes. `key` changes (e.g. the node's
// credential) refetch, since a credential-scoped URL depends on it.
export function useNodeWebhooks(workflowId: string | undefined, key = '') {
  return useQuery<NodeWebhook[]>({
    queryKey: [...triggerKeys.webhooks(workflowId ?? ''), key],
    queryFn: () => triggerService.webhooks(workflowId as string),
    enabled: !!workflowId,
  });
}

export function useNodeOptions(
  nodeKey: string,
  property: string,
  credentialId: string | undefined,
  needsCredential: boolean,
) {
  return useQuery<NodeOption[], Error>({
    queryKey: triggerKeys.options(nodeKey, property, credentialId),
    queryFn: async () => {
      try {
        return await triggerService.loadOptions(nodeKey, property, credentialId);
      } catch (error) {
        throw new Error(errorMessage(error, 'Options could not be loaded'), { cause: error });
      }
    },
    enabled: !needsCredential || !!credentialId,
    retry: false,
  });
}

const POLL_MS = 2000;

// "Listen for test event": starts a listen, polls until an event arrives or
// it expires, and stops it when the panel goes away.
export function useTestListen(workflowId: string, nodeId: string) {
  const [listen, setListen] = useState<TestListen | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const active = useRef<string | null>(null);

  useEffect(() => {
    if (!listen || listen.status !== 'waiting') return;
    const timer = window.setInterval(() => {
      triggerService
        .testListen(listen.listenId)
        .then((next) => {
          if (active.current === next.listenId) setListen(next);
        })
        .catch(() => undefined);
    }, POLL_MS);
    return () => window.clearInterval(timer);
  }, [listen]);

  // Leaving the node (or the page) stops a listen still waiting.
  useEffect(
    () => () => {
      if (active.current) void triggerService.stopTestListen(active.current).catch(() => undefined);
    },
    [workflowId, nodeId],
  );

  const start = useCallback(async () => {
    setError(null);
    setStarting(true);
    try {
      const started = await triggerService.startTestListen(workflowId, nodeId);
      active.current = started.listenId;
      setListen(started);
    } catch (cause) {
      setError(errorMessage(cause, 'Could not start listening'));
    } finally {
      setStarting(false);
    }
  }, [workflowId, nodeId]);

  const stop = useCallback(async () => {
    const listenId = active.current;
    active.current = null;
    setListen(null);
    if (listenId) await triggerService.stopTestListen(listenId).catch(() => undefined);
  }, []);

  return { listen, error, starting, start, stop };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { errorMessage, triggerService } from '../services/trigger.service';
import { credentialKeys } from './useCredentials';

interface CallbackMessage {
  type?: unknown;
  status?: unknown;
  credentialId?: unknown;
  message?: unknown;
}

// Connects an OAuth2 credential in a pop-up. The callback page posts
// { type: 'oauth2-callback', status, credentialId | message } and closes.
export function useOAuth2Popup(onConnected?: (credentialId: string) => void) {
  const queryClient = useQueryClient();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const waitingFor = useRef<string | null>(null);

  useEffect(() => {
    const handle = (event: MessageEvent<CallbackMessage>) => {
      if (event.data?.type !== 'oauth2-callback' || !waitingFor.current) return;
      waitingFor.current = null;
      setPending(false);
      if (event.data.status === 'success' && typeof event.data.credentialId === 'string') {
        setError(null);
        void queryClient.invalidateQueries({ queryKey: credentialKeys.all });
        void queryClient.invalidateQueries({ queryKey: ['node-options'] });
        onConnected?.(event.data.credentialId);
      } else {
        setError(typeof event.data.message === 'string' ? event.data.message : 'Sign-in failed');
      }
    };
    window.addEventListener('message', handle);
    return () => window.removeEventListener('message', handle);
  }, [onConnected, queryClient]);

  const connect = useCallback(async (credentialId: string) => {
    setError(null);
    setPending(true);
    waitingFor.current = credentialId;
    // Opened before the request so pop-up blockers allow it.
    const popup = window.open('', 'oauth2', 'width=600,height=700');
    try {
      const url = await triggerService.oauth2Url(credentialId);
      if (popup) popup.location.href = url;
      else window.open(url, 'oauth2', 'width=600,height=700');
      // Closing the pop-up without finishing must not leave the button waiting.
      const watch = window.setInterval(() => {
        if (!popup || popup.closed) {
          window.clearInterval(watch);
          setPending(false);
        }
      }, 500);
    } catch (cause) {
      popup?.close();
      waitingFor.current = null;
      setPending(false);
      setError(errorMessage(cause, 'Sign-in could not start'));
    }
  }, []);

  return { connect, pending, error };
}

