import { useDesignerStore } from '../../store/designer.store';
import { Play, Settings, AlertCircle } from 'lucide-react';
import { cn } from '@/lib/utils';

interface NodeProps {
  id?: string;
  data: {
    name: string;
    key: string;
    config?: Record<string, unknown>;
  };
}

export function TriggerNode({ id, data }: NodeProps) {
  const nodeTypes = useDesignerStore((state) => state.nodeTypes);
  const validationIssues = useDesignerStore((state) => state.validationIssues);
  const nodeType = nodeTypes.find((t) => t.key === data.key);
  const color = nodeType?.color || '#6b7280'; // default gray

  const errorCount = id
    ? validationIssues.filter((i) => i.nodeId === id).length
    : 0;

  return (
    <div className="relative group">
