42	// Raised when a per_item node fails part-way; carries the progress summary for the log.
43	class ItemRunError extends Error {
44	  constructor(
45	    message: string,
46	    readonly summary: {
47	      total_items: number;
48	      processed: number;
49	      failed_at_index: number;
50	    },
51	  ) {
