56	export class NodeRunner {
57	  constructor(
58	    private readonly repository: ExecutionRepository,
59	    private readonly executors: ReadonlyMap<string, INodeExecutor>,
60	  ) {}
61	
62	  async run(params: NodeRunParams): Promise<NodeRunResult> {
63	    const { node, items } = params;
64	    const startedAt = new Date();
65	
66	    try {
67	      const executor = this.executors.get(node.data?.key);
68	      if (!executor) {
69	        throw new Error(
70	          `No executor registered for node key: ${String(node.data?.key)}`,
71	        );
72	      }
73	
74	      const rawConfig = applySchemaDefaults(
75	        toRecord(node.data.config),
76	        params.configSchema,
77	      );
78	      const output =
79	        executor.runMode === 'once'
80	          ? await this.runOnce(executor, rawConfig, params)
81	          : await this.runPerItem(executor, rawConfig, params);
82	
83	      return {
84	        log: {
85	          nodeId: node.id,
86	          nodeKey: node.data.key,
87	          status: ExecutionStatus.SUCCESS,
88	          input: items,
89	          output,
90	          startedAt,
91	          finishedAt: new Date(),
92	        },
93	        output,
94	        status: ExecutionStatus.SUCCESS,
95	      };
96	    } catch (error) {
97	      const message =
98	        error instanceof Error ? error.message : 'Node execution failed';
99	      return {
100	        log: {
101	          nodeId: node.id,
102	          nodeKey: node.data?.key ?? 'unknown',
103	          status: ExecutionStatus.FAILED,
104	          input: items,
105	          output: error instanceof ItemRunError ? error.summary : null,
106	          errorMessage: sanitizeErrorText(message),
107	          startedAt,
108	          finishedAt: new Date(),
109	        },
110	        output: [],
111	        status: ExecutionStatus.FAILED,
112	      };
113	    }
114	  }
115	
116	  private async runOnce(
117	    executor: IOnceExecutor,
118	    rawConfig: Record<string, unknown>,
119	    params: NodeRunParams,
120	  ): Promise<Item[]> {
121	    const secret = <REDACTED> this.resolveCredential(
122	      executor,
123	      rawConfig,
124	      params.credentialOwnerId,
125	    );
126	    const currentItem = params.items[0] ?? { json: {} };
127	    const config = executor.parseConfig(
128	      resolveConfig(
129	        rawConfig,
130	        params.configSchema,
131	        createExpressionContext({
132	          runs: params.runs,
133	          names: params.names,
134	          currentItem,
135	          currentIndex: 0,
136	        }),
137	      ),
138	    );
139	
140	    const output = await executor.execute({
141	      config,
142	      items: params.items,
143	      credential: secret,
144	    });
145	    if (
146	      !Array.isArray(output) ||
147	      !output.every((item) => isPlainObject(item) && isPlainObject(item.json))
148	    ) {
149	      throw new Error('Node returned an invalid list of items');
150	    }
151	    return output;
152	  }
153	
154	  private async runPerItem(
155	    executor: IPerItemExecutor,
156	    rawConfig: Record<string, unknown>,
157	    params: NodeRunParams,
158	  ): Promise<Item[]> {
159	    const { items } = params;
160	    // Nothing to process: no credential lookup, no config validation.
161	    if (items.length === 0) return [];
162	
163	    const cap = executor.maxItems?.(rawConfig);
164	    if (cap && items.length > cap.limit) {
165	      throw new Error(
166	        `Node received ${items.length} items, which exceeds ${cap.reason}`,
167	      );
168	    }
169	
170	    const secret = <REDACTED> this.resolveCredential(
171	      executor,
172	      rawConfig,
173	      params.credentialOwnerId,
174	    );
175	    const output: Item[] = [];
176	
177	    for (let index = 0; index < items.length; index += 1) {
178	      try {
179	        const config = executor.parseConfig(
180	          resolveConfig(
181	            rawConfig,
182	            params.configSchema,
183	            createExpressionContext({
184	              runs: params.runs,
185	              names: params.names,
186	              currentItem: items[index],
187	              currentIndex: index,
188	            }),
189	          ),
190	        );
191	        const result = await executor.executeItem({
192	          config,
193	          item: items[index],
194	          credential: secret,
195	        });
196	
197	        const jsons =
198	          result === null || result === undefined
199	            ? []
200	            : Array.isArray(result)
201	              ? result
202	              : [result];
203	        for (const json of jsons) {
204	          if (!isPlainObject(json)) {
205	            throw new Error('Node returned an invalid item');
206	          }
207	          output.push({ json, pairedItem: index });
208	        }
209	      } catch (error) {
210	        throw new ItemRunError(
211	          error instanceof Error ? error.message : 'Node execution failed',
212	          {
213	            total_items: items.length,
214	            processed: index,
215	            failed_at_index: index,
216	          },
217	        );
218	      }
219	    }
220	    return output;
221	  }
222	
223	  // Runs once per node (not per item); credential_id is never an expression.
224	  private async resolveCredential(
225	    executor: INodeExecutor,
226	    rawConfig: Record<string, unknown>,
227	    ownerId: string,
228	  ): Promise<unknown> {
229	    const candidate = rawConfig.credential_id;
230	    if (candidate === undefined) return null;
231	    if (typeof candidate !== 'string' || !UUID_PATTERN.test(candidate)) {
232	      throw new BadRequestException('Invalid credential ID format');
233	    }
234	
235	    const resolved = await this.repository.resolveCredential(
236	      candidate,
237	      ownerId,
238	    );
239	    if (!resolved) throw new Error('credential was not found');
240	
241	    const expected = executor.expectedConnectorKey?.(rawConfig);
242	    if (expected && resolved.connectorKey !== expected) {
243	      throw new Error(
244	        `Credential does not belong to the "${expected}" connector`,
245	      );
246	    }
247	    return resolved.secret;
248	  }
249	}
