1	import { ExecutionRepository } from '../../domain/repositories/execution.repository';
2	import { WorkflowVersionForExecution } from '../../domain/models/execution.types';
3	import {
4	  ExecutionStatus,
5	  TriggerType,
6	} from '../../domain/constants/execution.constants';
7	import {
8	  getExecutionOrder,
9	  WorkflowDefinition,
10	} from '../../domain/entities/workflow-execution.entity';
11	import { INodeExecutor } from '../../domain/entities/node-executor';
12	import { buildNodeNameIndex, NodeRun } from '../../domain/entities/run-state';
13	import { Item } from '../../domain/models/item';
14	import { NodeCatalogPort } from '../ports/node-catalog.port';
15	import { NodeRunner } from './node-runner';
16	
17	export interface StartRunInput {
18	  version: WorkflowVersionForExecution;
19	  triggerType: TriggerType;
20	  triggeredById: string | null;
21	  // Input of the first node: [] for a manual run, the payload for a webhook.
22	  triggerItems: Item[];
23	}
24	
25	// Runs a published version node by node. Shared by the manual (synchronous)
26	// path and the queue processor (webhook).
27	export class WorkflowEngine {
28	  private readonly runner: NodeRunner;
29	
30	  constructor(
31	    private readonly repository: ExecutionRepository,
32	    executors: INodeExecutor[],
33	    private readonly catalog: NodeCatalogPort,
34	  ) {
35	    this.runner = new NodeRunner(
36	      repository,
37	      new Map(executors.map((executor) => [executor.key, executor])),
38	    );
39	  }
40	
41	  // Throws when the definition cannot be run, before anything is stored.
42	  executionOrder(definition: unknown): string[] {
43	    return getExecutionOrder(definition);
44	  }
45	
46	  async createExecution(input: StartRunInput, startedAt: Date) {
47	    return this.repository.createExecution({
48	      workflowId: input.version.workflowId,
49	      workflowVersionId: input.version.id,
50	      triggerType: input.triggerType,
51	      triggeredById: input.triggeredById,
52	      startedAt,
53	      context:
54	        input.triggerType === TriggerType.MANUAL
55	          ? undefined
56	          : { triggerItems: input.triggerItems },
57	    });
58	  }
59	
60	  async run(
61	    executionId: string,
62	    version: WorkflowVersionForExecution,
63	    triggerItems: Item[],
64	    startedAt: Date,
65	  ): Promise<ExecutionStatus> {
66	    // Stays FAILED if anything unexpected throws (e.g. the database), so the
67	    // execution is never left RUNNING.
68	    let finalStatus = ExecutionStatus.FAILED;
69	    try {
70	      finalStatus = await this.runNodes(executionId, version, triggerItems);
71	    } finally {
72	      const finishedAt = new Date();
73	      await this.repository.finishExecution(
74	        executionId,
75	        finalStatus,
76	        finishedAt,
77	        finishedAt.getTime() - startedAt.getTime(),
78	      );
79	    }
80	    return finalStatus;
81	  }
82	
83	  private async runNodes(
84	    executionId: string,
85	    version: WorkflowVersionForExecution,
86	    triggerItems: Item[],
87	  ): Promise<ExecutionStatus> {
88	    const order = this.executionOrder(version.definition);
89	    const definition = version.definition as WorkflowDefinition;
90	    const nodes = new Map(definition.nodes.map((node) => [node.id, node]));
91	    const names = buildNodeNameIndex(definition.nodes);
92	    // A malformed node without a key must fail on its own (no executor),
93	    // not break the catalog lookup for the whole run.
94	    const nodeKeys = definition.nodes
95	      .map((node) => node.data?.key)
96	      .filter((key): key is string => typeof key === 'string');
97	    const configSchemas = await this.catalog.getConfigSchemas([
98	      ...new Set(nodeKeys),
99	    ]);
100	
101	    const runs: NodeRun[] = [];
102	    let items: Item[] = triggerItems;
103	    let status = ExecutionStatus.SUCCESS;
104	
105	    for (const nodeId of order) {
106	      const node = nodes.get(nodeId)!;
107	      const result = await this.runner.run({
108	        node,
109	        items,
110	        runs,
111	        names,
112	        configSchema: configSchemas.get(node.data?.key),
113	        credentialOwnerId: version.workflowOwnerId,
114	      });
115	
116	      await this.repository.saveNodeLog(executionId, result.log);
117	
118	      if (result.status === ExecutionStatus.FAILED) {
119	        status = ExecutionStatus.FAILED;
120	        break;
121	      }
122	      runs.push({
123	        nodeId: node.id,
124	        nodeName: typeof node.data.name === 'string' ? node.data.name : node.id,
125	        input: items,
126	        output: result.output,
127	      });
128	      items = result.output;
129	    }
130	    return status;
131	  }
132	}
