1	import { NodeReferenceError, PairedItemError } from '../expression/errors';
2	import { ExpressionContext } from '../expression/template';
3	import { Item, ItemJson } from '../models/item';
4	
5	export interface NodeRun {
6	  nodeId: string;
7	  nodeName: string;
8	  input: Item[];
9	  output: Item[];
10	}
11	
12	// node display name -> ids of the nodes carrying that name
13	export type NodeNameIndex = ReadonlyMap<string, readonly string[]>;
14	
15	export function buildNodeNameIndex(
16	  nodes: ReadonlyArray<{ id: string; data?: Record<string, unknown> }>,
17	): NodeNameIndex {
18	  const index = new Map<string, string[]>();
19	  for (const node of nodes) {
20	    const name = node.data?.name;
21	    if (typeof name !== 'string' || name.length === 0) continue;
22	    index.set(name, [...(index.get(name) ?? []), node.id]);
23	  }
24	  return index;
25	}
26	
27	function findRunIndex(
28	  runs: readonly NodeRun[],
29	  names: NodeNameIndex,
30	  nodeName: string,
31	): number {
32	  const ids = names.get(nodeName);
33	  if (!ids || ids.length === 0) {
34	    throw new NodeReferenceError(
35	      `Node "${nodeName}" was not found - it may have been renamed`,
36	    );
37	  }
38	  if (ids.length > 1) {
39	    throw new NodeReferenceError(
40	      `Node name "${nodeName}" is used by ${ids.length} nodes; rename them so the reference is unambiguous`,
41	    );
42	  }
43	  const runIndex = runs.findIndex((run) => run.nodeId === ids[0]);
44	  if (runIndex === -1) {
45	    throw new NodeReferenceError(
46	      `Node "${nodeName}" has not run before this node`,
47	    );
48	  }
49	  return runIndex;
50	}
51	
52	// `runs` are the nodes that already ran, in order; the node being executed
53	// received `runs[last].output` as input. `currentIndex` is the position of the
54	// current item in that input.
55	export function createExpressionContext(params: {
56	  runs: readonly NodeRun[];
57	  names: NodeNameIndex;
58	  currentItem: Item;
59	  currentIndex: number;
60	}): ExpressionContext {
61	  const { runs, names, currentItem, currentIndex } = params;
62	
63	  return {
64	    currentItem,
65	
66	    getNodeAll(nodeName: string): ItemJson[] {
67	      return runs[findRunIndex(runs, names, nodeName)].output.map(
68	        (item) => item.json,
69	      );
70	    },
71	
72	    getPairedJson(nodeName: string): ItemJson {
73	      const targetPos = findRunIndex(runs, names, nodeName);
74	      let index = currentIndex;
75	      for (let pos = runs.length - 1; pos >= targetPos; pos -= 1) {
76	        const item = runs[pos].output[index];
77	        if (item === undefined) {
78	          throw new PairedItemError(
79	            `There is no item to pair with node "${nodeName}"`,
80	          );
81	        }
82	        if (pos === targetPos) return item.json;
83	        if (item.pairedItem === undefined) {
84	          throw new PairedItemError(
85	            `Cannot tell which item of node "${nodeName}" matches the current item. Use $node["${nodeName}"].all to read all of its items`,
86	          );
87	        }
88	        index = item.pairedItem;
89	      }
90	      throw new PairedItemError(
91	        `There is no item to pair with node "${nodeName}"`,
92	      );
93	    },
94	  };
95	}
96

