import { getExecutionOrder } from '@app/execution/domain/entities/workflow-execution.entity';

const node = (id: string) => ({ id, data: { key: 'k' } });
const edge = (source: string, target: string) => ({ source, target });

describe('getExecutionOrder', () => {
  const nodes = ['a', 'b', 'c', 'd'].map(node);

  it('follows a chain stored in order', () => {
    const edges = [edge('a', 'b'), edge('b', 'c'), edge('c', 'd')];
    expect(getExecutionOrder({ nodes, edges })).toEqual(['a', 'b', 'c', 'd']);
  });

  it('follows a chain whose edges were drawn out of order', () => {
    const edges = [edge('c', 'd'), edge('a', 'b'), edge('b', 'c')];
    expect(getExecutionOrder({ nodes, edges })).toEqual(['a', 'b', 'c', 'd']);
  });

  it.each([
    ['a node with two outgoing edges', [edge('a', 'b'), edge('a', 'c')]],
    ['a node with two incoming edges', [edge('a', 'c'), edge('b', 'c')]],
    ['two separate chains', [edge('a', 'b'), edge('c', 'd')]],
    ['a cycle', [edge('a', 'b'), edge('b', 'a')]],
  ])('rejects %s', (_name, edges) => {
    expect(() => getExecutionOrder({ nodes, edges })).toThrow(
      /single directed chain/,
    );
  });

  it('rejects an edge that points to a deleted node', () => {
    expect(() =>
      getExecutionOrder({ nodes, edges: [edge('a', 'gone')] }),
    ).toThrow(/missing node: gone/);
  });

  it('rejects a definition without edges', () => {
    expect(() => getExecutionOrder({ nodes, edges: [] })).toThrow(
      /non-empty edge chain/,
    );
  });
});
﻿import {
  NodeReferenceError,
  PairedItemError,
} from '@app/execution/domain/expression/errors';
import { Item } from '@app/execution/domain/models/item';
import {
  buildNodeNameIndex,
  createExpressionContext,
  NodeRun,
} from '@app/execution/domain/entities/run-state';

const item = (json: Record<string, unknown>, pairedItem?: number): Item => ({
  json,
  pairedItem,
});

const nodes = [
  { id: 'trigger', data: { name: 'Start' } },
  { id: 'sheet', data: { name: 'Read Customers' } },
  { id: 'filter', data: { name: 'Only New' } },
  { id: 'agg', data: { name: 'Gather' } },
  { id: 'dupA', data: { name: 'Twin' } },
  { id: 'dupB', data: { name: 'Twin' } },
  { id: 'later', data: { name: 'Later' } },
];
const names = buildNodeNameIndex(nodes);

const sheetOut = [
  item({ email: 'kiet@x.com' }),
  item({ email: 'an@x.com' }),
  item({ email: 'minh@x.com' }),
];
// Filter keeps rows 0 and 2 of the sheet output.
const filterOut = [item(sheetOut[0].json, 0), item(sheetOut[2].json, 2)];

const runs: NodeRun[] = [
  { nodeId: 'trigger', nodeName: 'Start', input: [], output: [item({})] },
  {
    nodeId: 'sheet',
    nodeName: 'Read Customers',
    input: [item({})],
    output: sheetOut,
  },
  {
    nodeId: 'filter',
    nodeName: 'Only New',
    input: sheetOut,
    output: filterOut,
  },
];

const contextFor = (currentIndex: number, usedRuns: NodeRun[] = runs) =>
  createExpressionContext({
    runs: usedRuns,
    names,
    currentItem: usedRuns[usedRuns.length - 1].output[currentIndex],
    currentIndex,
  });

describe('createExpressionContext', () => {
  it('pairs the current item with the matching item of an earlier node', () => {
    // 2nd filter output (index 1) came from sheet row 2.
    expect(contextFor(1).getPairedJson('Read Customers')).toEqual({
      email: 'minh@x.com',
    });
    expect(contextFor(0).getPairedJson('Read Customers')).toEqual({
      email: 'kiet@x.com',
    });
  });

  it('returns the item of the node directly before the current one', () => {
    expect(contextFor(1).getPairedJson('Only New')).toEqual({
      email: 'minh@x.com',
    });
  });

  it('returns every item of a node with getNodeAll', () => {
    expect(contextFor(0).getNodeAll('Read Customers')).toEqual([
      { email: 'kiet@x.com' },
      { email: 'an@x.com' },
    private readonly repository: ExecutionRepository,
    @Inject('NODE_EXECUTORS') executors: INodeExecutor[],
    catalog: NodeCatalogPort,
  ) {
    this.engine = new WorkflowEngine(repository, executors, catalog);
  }

  private async validateAndFetchWorkflow(
    versionId: string,
    actorId: string,
  ): Promise<WorkflowVersionForExecution> {
    const version = await this.repository.findVersion(versionId);
    if (!version) throw new NotFoundException('Workflow version not found');

    const isAllowed = version.workflowOwnerId === actorId;
    if (!isAllowed) {
      throw new ForbiddenException('You cannot run this workflow');
    }
    return version;
  }

  private checkExecutionOrder(definition: unknown): void {
    try {
      this.engine.executionOrder(definition);
    } catch (error) {
      throw new BadRequestException(
        error instanceof Error ? error.message : 'Invalid workflow definition',
      );
    }
  }

  async execute(command: StartExecutionCommand) {
    const version = await this.validateAndFetchWorkflow(
      command.workflowVersionId,
      command.actorId,
    );
    this.checkExecutionOrder(version.definition);

    const startedAt = new Date();
    const executionId = await this.engine.createExecution(
      {
        version,
        triggerType: TriggerType.MANUAL,
        triggeredById: command.actorId,
        triggerItems: [],
      },
