import {
  ActionNode,
  AppApiError,
  nodeParameters,
  PackageRegistry,
} from '@app/apps';
import {
  INodeExecutor,
  IPerItemExecutor,
} from '../../domain/entities/node-executor';
import { PassThroughTriggerExecutor } from './pass-through-trigger-executor';
import { PackageActionLimits } from '../../domain/constants/execution.constants';
import { Item, ItemJson } from '../../domain/models/item';
import { Sleep } from './llm-generate-executor';

type Parameters = Record<string, unknown>;

const defaultSleep: Sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Runs an action node of an integration package for each item: the engine
// resolves expressions and the credential, the package talks to the app.
export class PackageActionExecutor implements IPerItemExecutor<Parameters> {
  readonly runMode = 'per_item' as const;
  readonly key: string;

  constructor(
    private readonly node: ActionNode,
    private readonly sleep: Sleep = defaultSleep,
  ) {
    this.key = node.key;
  }

  // Required fields must not resolve to blank (e.g. an expression whose
  // field is missing in the item).
  parseConfig(raw: unknown): Parameters {
    const parameters = nodeParameters(raw);
    for (const property of this.node.properties) {
      if (!property.required) continue;
      const value = parameters[property.name];
      if (
        value === undefined ||
        value === null ||
        (typeof value === 'string' && value.trim() === '')
      ) {
        throw new Error(`${property.displayName} is required`);
      }
    }
    return parameters;
  }

  expectedConnectorKey(): string | null {
    return this.node.credentialType ?? null;
  }

  async executeItem(params: {
    config: Parameters;
    item: Item;
    credential: unknown;
  }): Promise<ItemJson | ItemJson[] | null> {
    const credential =
      params.credential && typeof params.credential === 'object'
        ? (params.credential as Record<string, unknown>)
        : null;
    if (this.node.credentialType && !credential) {
      throw new Error('Choose a credential for this node');
    }
    return this.withRetry(() =>
      this.node.execute({
        parameters: params.config,
        credential,
        item: { json: params.item.json },
      }),
    );
  }

  // Rate limits and outages are retried with a growing pause; anything else
  // (e.g. Messenger's 24-hour window, revoked access) fails at once.
  private async withRetry<T>(attempt: () => Promise<T>): Promise<T> {
    for (let retry = 0; ; retry += 1) {
      try {
        return await attempt();
      } catch (error) {
        const retryable = error instanceof AppApiError && error.retryable;
        if (!retryable || retry >= PackageActionLimits.MAX_RETRIES) throw error;
        await this.sleep(1000 * 2 ** retry);
      }
    }
  }
}

// Executors of every package node: a trigger passes its event on (the event
// is the run's input), an action runs per item.
export function packageExecutors(registry: PackageRegistry): INodeExecutor[] {
  return registry
    .allNodes()
    .map((node) =>
      node.kind === 'action'
        ? new PackageActionExecutor(node)
        : new PassThroughTriggerExecutor(node.key),
    );
}
import { Injectable, Logger, OnApplicationBootstrap } from '@nestjs/common';
import { ConnectorAuthType, NodeCategory } from '@prisma/client';
import { PrismaService } from '@app/database';
import {
  credentialConfigSchema,
  nodeConfigSchema,
  PackageRegistry,
} from '@app/apps';

// Integration packages are the source of truth for their node and credential
// types: they are written into the catalog every time the server starts, so a
// new package needs no seed change.
@Injectable()
export class PackageCatalogSync implements OnApplicationBootstrap {
  private readonly logger = new Logger(PackageCatalogSync.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly registry: PackageRegistry,
  ) {}

  async onApplicationBootstrap(): Promise<void> {
    await this.sync();
  }

  async sync(): Promise<void> {
    const connectorIds = new Map<string, string>();
    for (const credential of this.registry.allCredentialTypes()) {
      const data = {
        name: credential.displayName,
        authType: credential.oauth2
          ? ConnectorAuthType.OAUTH2
          : ConnectorAuthType.API_KEY,
        configSchema: credentialConfigSchema(credential) as object,
        isActive: true,
      };
      const row = await this.prisma.connector.upsert({
        where: { key: credential.key },
        update: data,
        create: { key: credential.key, ...data },
      });
      connectorIds.set(credential.key, row.id);
    }

    const nodes = this.registry.allNodes();
    for (const node of nodes) {
      const data = {
        displayName: node.displayName,
        icon: node.icon,
        color: node.color,
        category:
          node.kind === 'trigger'
            ? NodeCategory.TRIGGER
            : NodeCategory.INTEGRATION,
        description: node.description,
        configSchema: nodeConfigSchema(node) as object,
        inputSchema: { type: 'object' },
        outputSchema: { type: 'object' },
        connectorId: node.credentialType
          ? (connectorIds.get(node.credentialType) ?? null)
          : null,
        isActive: true,
      };
      await this.prisma.nodeTypeDefinition.upsert({
        where: { key: node.key },
        update: data,
        create: { key: node.key, ...data },
      });
    }
    this.logger.log(
      `Synced ${nodes.length} node types and ${connectorIds.size} credential types from ${this.registry.packages.length} packages`,
    );
  }
}
import { IntegrationPackage } from './core/package';
import { webhookPackage } from './webhook/webhook.package';
import { createMessengerPackage } from './messenger/messenger.package';
import { MetaGraphApi } from './messenger/meta-graph.api';

export interface PackageDependencies {
  metaGraph: MetaGraphApi;
}

// The installed integration packages. Adding an app = one line here.
export function createPackages(
  deps: PackageDependencies,
): IntegrationPackage[] {
  return [webhookPackage, createMessengerPackage(deps.metaGraph)];
}
import { Module } from '@nestjs/common';
import { PackageRegistry } from './core/package-registry';
import { createPackages } from './packages';
import { HttpMetaGraphApi, MetaGraphApi } from './messenger/meta-graph.api';

// Replaceable in tests so nothing is sent to Facebook.
export const META_GRAPH_API = 'META_GRAPH_API';

@Module({
  providers: [
    { provide: META_GRAPH_API, useClass: HttpMetaGraphApi },
    {
      provide: PackageRegistry,
      useFactory: (metaGraph: MetaGraphApi) =>
        new PackageRegistry(createPackages({ metaGraph })),
      inject: [META_GRAPH_API],
    },
  ],
  exports: [PackageRegistry, META_GRAPH_API],
})
export class AppsModule {}
import {
  IntegrationPackage,
  TriggerNode,
  WebhookRequest,
} from '../core/package';
import { header } from '../core/text';

// Credentials of the caller must not end up in execution logs.
const HIDDEN_HEADERS = new Set([
  'authorization',
  'proxy-authorization',
  'cookie',
  'x-api-key',
]);

// Any system that can send an HTTP POST. Each node has its own secret URL,
// which is the only credential.
export const webhookTrigger: TriggerNode = {
  kind: 'trigger',
  key: 'webhook.trigger',
  displayName: 'Webhook',
  description: 'Start when an HTTP POST arrives at this node’s URL',
  icon: 'webhook',
  color: '#6366F1',
  properties: [],
  webhook: {
    scope: 'node',
    handle({ request }) {
      if (request.method !== 'POST') {
        return {
          status: 405,
          body: { success: false, message: 'Send a POST request' },
          events: [],
        };
      }
      const idempotencyKey = header(request.headers, 'idempotency-key')?.trim();
      return {
        status: 202,
        events: [
          {
            ...(idempotencyKey ? { id: idempotencyKey } : {}),
            json: webhookJson(request, new Date()),
          },
        ],
      };
    },
  },
};

export function webhookJson(
  request: WebhookRequest,
  receivedAt: Date,
): Record<string, unknown> {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(request.headers)) {
    if (value === undefined || HIDDEN_HEADERS.has(name.toLowerCase())) continue;
    headers[name.toLowerCase()] = Array.isArray(value)
      ? value.join(', ')
      : value;
  }
  return {
    body: request.body ?? null,
    query: request.query,
    headers,
    received_at: receivedAt.toISOString(),
  };
}

export const webhookPackage: IntegrationPackage = {
  key: 'webhook',
  displayName: 'Webhook',
  credentials: [],
  nodes: [webhookTrigger],
};

