18	export function resolveOutputs(schema: unknown, config: unknown): OutputDef[] {
19	  const spec = isRecord(schema) ? schema['x-outputs'] : undefined;
20	  const main = [{ key: MAIN_OUTPUT, label: 'Output' }];
