31	    const entries: unknown[] = Array.isArray(list) ? list : [];
32	    const labelField = typeof spec.labelField === 'string' ? spec.labelField : 'label';
33	    const outputs = entries.map((entry, index): OutputDef => {
34	      const label = isRecord(entry) ? entry[labelField] : undefined;
35	      const id = isRecord(entry) ? entry.id : undefined;
36	      return {
37	        key: typeof id === 'string' && id ? `rule_${id}` : `rule_${index}`,
38	        label: typeof label === 'string' && label.trim() ? label : `Rule ${index + 1}`,
39	      };
40	    });
41	    if (spec.fallback === true) outputs.push({ key: 'fallback', label: 'Fallback' });
42	    return outputs;
43	  }
44	  return main;
45	}
