const node = (id, type, key, name, x, y, config) =>
  nodes.push({ id, type, position: { x, y }, data: { key, name, config } });
const link = (source, target, handle) =>
  edges.push({ id: `e-${source}-${target}`, source, target, sourceHandle: handle || 'right-source', targetHandle: 'left-target' });

const send = (config) => ({ page_id: PAGE, credential_id: MSG_CRED, recipient_id: SENDER, message_type: 'text', ...config });
const llm = (config) => ({ provider: 'gemini', credential_id: LLM_CRED, model: 'gemini-3.5-flash-lite', max_tokens: 1024, output_format: 'text', max_items: 50, ...config });
const cond = (value1, operator, value2) => ({ value1, operator, value2: value2 ?? '' });

node('trigger', 'triggerNode', 'messenger.trigger', 'Messenger Trigger', 0, 300, { page_id: PAGE, credential_id: MSG_CRED, events: 'all' });

node('route', 'actionNode', 'logic.switch', 'Switch', 300, 300, {
  mode: 'first', ignore_case: true, ignore_accents: true,
  rules: [
    { id: 'askai', label: 'Ask AI', combine: 'and', conditions: [cond(PAYLOAD, 'equals', 'AI')] },
    { id: 'menu', label: 'Menu', combine: 'and', conditions: [cond(T, 'contains', 'menu')] },
    { id: 'price', label: 'Price', combine: 'or', conditions: [cond(PAYLOAD, 'equals', 'GIA'), cond(T, 'contains', 'gia')] },
    { id: 'order', label: 'Order', combine: 'and', conditions: [cond(T, 'contains', 'don hang')] },
  ],
});
link('trigger', 'route');

// Ask AI
node('intro', 'actionNode', 'messenger.sendMessage', 'Send intro', 650, 0, send({ text: 'Bạn muốn hỏi gì? Cứ nhắn câu hỏi, mình trả lời ngay.' }));
link('route', 'intro', 'out:rule_askai');

// Menu
node('menu', 'actionNode', 'messenger.sendMessage', 'Send menu', 650, 130, send({
  message_type: 'quick_replies', text: 'Bạn muốn gì?',
  quick_replies: [{ title: 'Xem giá', payload: 'GIA' }, { title: 'Hỏi AI', payload: 'AI' }],
}));
link('route', 'menu', 'out:rule_menu');

// Price: sheet -> aggregate -> LLM -> send
node('sheet', 'actionNode', 'integration.google_sheet.readRows', 'Price sheet', 650, 270, { spreadsheet_id: '', sheet_name: 'Sheet1' });
node('aggregate', 'actionNode', 'data.aggregate', 'Price list', 950, 270, { field: 'items' });
node('priceLlm', 'actionNode', 'ai.llm.generate', 'Price answer', 1250, 270, llm({
  system_prompt: 'Bạn là nhân viên bán hàng. Chỉ trả lời dựa trên bảng giá được cung cấp, ngắn gọn bằng tiếng Việt, mỗi sản phẩm một dòng. Nếu không có trong bảng thì nói chưa có thông tin.',
  prompt: `Bảng giá: {{$json.items}}\nKhách hỏi: ${T}`,
}));
node('sendPrice', 'actionNode', 'messenger.sendMessage', 'Send price', 1550, 270, send({ text: '{{$node["Price answer"].json.text}}' }));
link('route', 'sheet', 'out:rule_price'); link('sheet', 'aggregate'); link('aggregate', 'priceLlm'); link('priceLlm', 'sendPrice');

// Order: http -> LLM -> send
node('http', 'actionNode', 'http.request', 'Order lookup', 650, 430, {
  method: 'GET', url: 'https://httpbin.org/get', authentication: 'none',
  query: [{ name: 'q', value: T }], body_type: 'none', timeout_ms: 30000, response_format: 'auto', fail_on_error_status: true,
});
node('orderLlm', 'actionNode', 'ai.llm.generate', 'Order answer', 950, 430, llm({
  system_prompt: 'Bạn là nhân viên chăm sóc khách hàng. Dựa vào dữ liệu đơn hàng được cung cấp, báo tình trạng đơn ngắn gọn bằng tiếng Việt. Nếu dữ liệu trống hoặc không có đơn thì nói không tìm thấy.',
  prompt: `Dữ liệu đơn hàng: {{$json.body}}\nKhách hỏi: ${T}`,
}));
node('sendOrder', 'actionNode', 'messenger.sendMessage', 'Send order', 1250, 430, send({ text: '{{$node["Order answer"].json.text}}' }));
link('route', 'http', 'out:rule_order'); link('http', 'orderLlm'); link('orderLlm', 'sendOrder');

